eriesId"]=14},["140028"]={["action"]=[[$N使出一记空翻，左手划了一个大弧，引天雷之力下劈，接着跃空，双爪忽左忽右交叉攻击$n的$l，此招唤作「$M」。]],["id"]=[[140028]],["moveId"]=30330,["seriesId"]=14},["140029"]={["action"]=[[$N使出一招「$M」，猛然间喉咙发出一声低喝，双爪左右交错出击，直取$n的$l，快若雷霆。]],["id"]=[[140029]],["moveId"]=30340,["seriesId"]=14},["14003"]={["action"]=[[$N步法轻盈，一式「$M」下劈单爪快如紫电，自击$n的$l。]],["id"]=[[14003]],["moveId"]=30040,["seriesId"]=14},["140030"]={["action"]=[[$N运转劲力到左手，使手心呈紫色，变掌为爪朝$n$l连劈三次，这一招「$M」似借雷威。]],["id"]=[[140030]],["moveId"]=30350,["seriesId"]=14},["140031"]={["action"]=[[$N急出一招「$M」，身姿轻盈一跃，双爪指尖冒出丝丝雷火，下劈迅猛，对准$n的$l连攻三次。]],["id"]=[[140031]],["moveId"]=30360,["seriesId"]=14},["140032"]={["action"]=[[$N一招「$M」，双爪高抬，以雷霆万钧之势对准$n的$l横劈三下。]],["id"]=[[140032]],["moveId"]=30370,["seriesId"]=14},["140033"]={["action"]=[[$N身形一沉，双足运转内力猛然蹬地而起，使出一招「$M」，双爪朝上直击，似三道粗雷劈向$n的$l。]],["id"]=[[140033]],["moveId"]=30390,["seriesId"]=14},["140034"]={["action"]=[[$N身形一沉，双足运转内力猛然蹬地而起，使出一招「$M」，双爪朝上直击，似三道粗雷劈向$n的$l。]],["id"]=[[140034]],["moveId"]=30400,["seriesId"]=14},["140035"]={["action"]=[[$N爪风隐隐带着雷声，一招「$M」如天罚之雷，两次横劈而出，随即身体腾空倒立，双爪朝下抓向$n的$l。]],["id"]=[[140035]],["moveId"]=30410,["seriesId"]=14},["140036"]={["action"]=[[$N展身虚步，提腰跃落，一招「$M」下劈如雷击，趁敌不备再次回身跳跃，对准$n的$l连续两次上劈。]],["id"]=[[140036]],["moveId"]=30420,["seriesId"]=14},["140037"]={["action"]=[[$N的脚下微微一点长啸一声，使出一招「$M」，以迅雷不及掩耳之势下劈双连，疾速上劈化做一道雷光，朝$n的$l攻击。]],["id"]=[[140037]],["moveId"]=30430,["seriesId"]=14},["140038"]={["action"]=[[$N一声冷笑，使出一招「$M」，纵身前跃，双爪乍然双连横劈前攻，接着攻势急转，道道劲雷朝$n的$l上劈而去。]],["id"]=[[140038]],["moveId"]=30440,["seriesId"]=14},["140039"]={["action"]=[[$N使出一记「$M」，将全身劲力灌注于双爪，劲力运雷光具现，朝前两次横劈，紧接着对准$n的$l下劈攻击。]],["id"]=[[140039]],["moveId"]=30460,["seriesId"]=14},["14004"]={["action"]=[[$N身形微晁抢前一步，运起十成功力，大喝一声，使出一招「$M」，单爪横扫挟紫雷之威击向$n的$l。]],["id"]=[[14004]],["moveId"]=30050,["seriesId"]=14},["140040"]={["action"]=[[$N使出一记「$M」，将全身劲力灌注于双爪，劲力运雷光具现，朝前两次横劈，紧接着对准$n的$l下劈攻击。]],["id"]=[[140040]],["moveId"]=30470,["seriesId"]=14},["140041"]={["action"]=[[$N左右手同出，使出一招「$M」，上劈接下劈变幻连连，如幻出数道闪电，随即身体跃空，双爪鬼魅般抓向$n的$l。]],["id"]=[[140041]],["moveId"]=30480,["seriesId"]=14},["140042"]={["action"]=[[$N左右手同出，使出一招「$M」，上劈接下劈变幻连连，如幻出数道闪电，随即身体跃空，双爪鬼魅般抓向$n的$l。]],["id"]=[[140042]],["moveId"]=30490,["seriesId"]=14},["140043"]={["action"]=[[$N一式「$M」，拔地而起，趁落地之势朝左下劈接右方上劈，落地后又旋身跃空，双爪化出一张无形的雷网罩住$n的$l。]],["id"]=[[140043]],["moveId"]=30500,["seriesId"]=14},["140044"]={["action"]=[[$N一道身影跃空，上劈下劈四道爪力飞劈向$n的$l，接着跃空，双爪袭向同一处，这正是一招「$M」，似浓云汇雷。]],["id"]=[[140044]],["moveId"]=30510,["seriesId"]=14},["14005"]={["action"]=[[$N步法轻盈，一式「$M」下劈单爪快如紫电，自击$n的$l。]],["id"]=[[14005]],["moveId"]=30060,["seriesId"]=14},["14006"]={["action"]=[[$N高高跃至半空，使出一招「$M」，单爪下劈，攻势凌厉，像罩开一张雷网，爪影重重地朝$n的$l攻去。]],["id"]=[[14006]],["moveId"]=30070,["seriesId"]=14},["14007"]={["action"]=[[$N轻轻跃起，一式「$M」疾速出击，单爪上攻指尖挥出雷光，直向$n的$l击去。]],["id"]=[[14007]],["moveId"]=30080,["seriesId"]=14},["14008"]={["action"]=[[$N高高跃至半空，使出一招「$M」，双爪攻势凌厉，像罩开一张雷网，爪影重重地朝$n的$l攻去。]],["id"]=[[14008]],["moveId"]=30100,["seriesId"]=14},["14009"]={["action"]=[[$N轻轻跃起，一式「$M」疾速出击，单爪上攻指尖挥出雷光，直向$n的$l击去。]],["id"]=[[14009]],["moveId"]=30110,["seriesId"]=14},["15001"]={["action"]=[[$N一式「$M」，左爪上下翻动形成无数爪影，连上劈洪水滔天般抓向$n的$l。]],["id"]=[[15001]],["moveId"]=30010,["seriesId"]=15},["150010"]={["action"]=[[$N飞身跳起，使出一招「$M」，双爪忽伸忽缩，诡奇绝伦，双连下劈如江水长流，不断直攻$n的$l。]],["id"]=[[150010]],["moveId"]=30120,["seriesId"]=15},["150011"]={["action"]=[[$N一声狂喝，身跃空中，使出一招「$M」，劲力如一泓秋水，直涌向双爪，对准$n的$l连续两次下劈。]],["id"]=[[150011]],["moveId"]=30130,["seriesId"]=15},["150012"]={["action"]=[[$N一招「$M」威力惊人，双腿突然发力，朝前猛跃，仿若飞瀑直泄，双连上劈攻向$n的$l。]],["id"]=[[150012]],["moveId"]=30140,["seriesId"]=15},["150013"]={["action"]=[[$N双手平伸，使出一招「$M」，身体跃空，十指有如海水奔腾，双爪横扫，直劈向$n的$l。]],["id"]=[[150013]],["moveId"]=30150,["seriesId"]=15},["150014"]={["action"]=[[$N双手平伸，使出一招「$M」，身体跃空，十指有如海水奔腾，双爪横扫，直劈向$n的$l。]],["id"]=[[150014]],["moveId"]=30170,["seriesId"]=15},["150015"]={["action"]=[[$N疾步向前冲去，一招「$M」向前横攻，双爪绵里藏针，以柔克刚，如活水般源源不断地攻击$n的$l。]],["id"]=[[150015]],["moveId"]=30180,["seriesId"]=15},["150016"]={["action"]=[[$N身形一晃而至，使出一招「$M」，双爪上劈接下劈带着一缕寒水，径直攻向$n的$l。]],["id"]=[[150016]],["moveId"]=30190,["seriesId"]=15},["150017"]={["action"]=[[$N暗运潜力，施展一招「$M」，双爪横出，左抓右砍，接而上劈，激发道道柔水般的劲力，朝$n的$l夹裹。]],["id"]=[[150017]],["moveId"]=30200,["seriesId"]=15},["150018"]={["action"]=[[$N暗运潜力，施展一招「$M」，双爪横出，左抓右砍，接而上劈，激发道道柔水般的劲力，朝$n的$l夹裹。]],["id"]=[[150018]],["moveId"]=30210,["seriesId"]=15},["150019"]={["action"]=[[$N疾步向前冲去，一式「$M」朝前横劈，随即身体腾空而起，双爪运劲出两道寒冰，对准$n的$l往下劈去。]],["id"]=[[150019]],["moveId"]=30220,["seriesId"]=15},["15002"]={["action"]=[[$N左手佯攻，右手使出一记「$M」，横劈似海水倾倒，摧枯拉朽般抓向$n的$l。]],["id"]=[[15002]],["moveId"]=30030,["seriesId"]=15},["150020"]={["action"]=[[$N使出一式「$M」横劈上前，随即身体跃空，对准$n的$l一记上劈，整套动作流水般自然顺畅。]],["id"]=[[150020]],["moveId"]=30240,["seriesId"]=15},["150021"]={["action"]=[[$N环舞一周，如水逐清荷，使出一招「$M」，双爪朝$n横劈，在$n后退时飞身上前，上劈攻其$l。]],["id"]=[[150021]],["moveId"]=30250,["seriesId"]=15},["150022"]={["action"]=[[$N使出一招「$M」，怒吼一声，双爪当头横劈$n，紧接着轻身一跃，从上而下激发数道阴寒水雾，罩向$n的$l]],["id"]=[[150022]],["moveId"]=30260,["seriesId"]=15},["150023"]={["action"]=[[$N突地一招「$M」，身体拔地而起，双爪挟着一阵水奔之势，猛地朝$n的$l双连上劈。]],["id"]=[[150023]],["moveId"]=30270,["seriesId"]=15},["150024"]={["action"]=[[$N背水一战，先出一爪，随即身形宛如飞鱼跃出水面，两爪齐出直击$n的$l。正是一招「$M」。]],["id"]=[[150024]],["moveId"]=30280,["seriesId"]=15},["150025"]={["action"]=[[$N腾空跳起，如踏浪行舟般使出一招「$M」，双爪互为阴阳，挟有水雾，浑然天成地两次击打$n的$l。]],["id"]=[[150025]],["moveId"]=30290,["seriesId"]=15},["150026"]={["action"]=[[只见$N心如止水，平地半空出爪连连，直取$n的$l，这一式「$M」使来当真行云流水。]],["id"]=[[150026]],["moveId"]=30300,["seriesId"]=15},["150027"]={["action"]=[[只见$N心如止水，平地半空出爪连连，直取$n的$l，这一式「$M」使来当真行云流水。]],["id"]=[[150027]],["moveId"]=30320,["seriesId"]=15},["150028"]={["action"]=[[只见$N平地一抓，出爪拖泥带水，却是虚招一晃，随后飞身一跃，两爪顺水推舟直击$n的$l。正是一招「$M」。]],["id"]=[[150028]],["moveId"]=30330,["seriesId"]=15},["150029"]={["action"]=[[$N使出一招「$M」，不管不顾、似要一瞬间分出胜负，双爪连发，如滴水穿石，绵绵不断劈向$n的$l。]],["id"]=[[150029]],["moveId"]=30340,["seriesId"]=15},["15003"]={["action"]=[[$N使出一招「$M」，单爪运劲下劈，仿若天河降落，横扫$n的$l。]],["id"]=[[15003]],["moveId"]=30040,["seriesId"]=15},["150030"]={["action"]=[[$N突然飞身上前，双爪反复来回击出，如骤雨般劈向$n的$l，速度快得令$n节奏大乱，正是一招「$M」。]],["id"]=[[150030]],["moveId"]=30350,["seriesId"]=15},["150031"]={["action"]=[[$N内力滔滔，一招「$M」信手拈来，双爪攻势浑厚下劈，连劈三次，掀起一阵水雾罩向$n的$l。]],["id"]=[[150031]],["moveId"]=30360,["seriesId"]=15},["150032"]={["action"]=[[$N使出一招「$M」，抬手如钩，运水寒之毒，三抓$n的$l。]],["id"]=[[150032]],["moveId"]=30370,["seriesId"]=15},["150033"]={["action"]=[[$N神情肃穆，使出一招「$M」，足尖离地滑行，双爪连劈，有如绵绵细雨，攻势始终对准$n的$l。]],["id"]=[[150033]],["moveId"]=30390,["seriesId"]=15},["150034"]={["action"]=[[$N神情肃穆，使出一招「$M」，足尖离地滑行，双爪连劈，有如绵绵细雨，攻势始终对准$n的$l。]],["id"]=[[150034]],["moveId"]=30400,["seriesId"]=15},["150035"]={["action"]=[[$N一招「$M」，双连横扫，身体飞至半空，锐利的双爪朝$n的$l攻去，恰如天河下倾。]],["id"]=[[150035]],["moveId"]=30410,["seriesId"]=15},["150036"]={["action"]=[[$N腾空飞起，一招「$M」下劈数道残影，身如水上浮鸟，落地后再次腾空，挟水寒之气上劈疾速，连续两次攻向$n的$l。]],["id"]=[[150036]],["moveId"]=30420,["seriesId"]=15},["150037"]={["action"]=[[$N身形晃动，使一式「$M」身如软水，忽左忽右下劈，乘势向前对准$n的$l上劈攻击。]],["id"]=[[150037]],["moveId"]=30430,["seriesId"]=15},["150038"]={["action"]=[[$N双爪朝$n横劈两次，转而再接上劈追击，犹如骤雨般攻向$n的$l，这一招「$M」爪影闪烁，令人防不胜防。]],["id"]=[[150038]],["moveId"]=30440,["seriesId"]=15},["150039"]={["action"]=[[$N脚踏流云，使出一招「$M」，疾速横劈两次，细水润无声般悄无声息地接连下劈，攻往$n的$l。]],["id"]=[[150039]],["moveId"]=30460,["seriesId"]=15},["15004"]={["action"]=[[$N单爪激发数道阴柔之气，如绵绵细雨横扫$n$l。]],["id"]=[[15004]],["moveId"]=30050,["seriesId"]=15},["150040"]={["action"]=[[$N脚踏流云，使出一招「$M」，疾速横劈两次，细水润无声般悄无声息地接连下劈，攻往$n的$l。]],["id"]=[[150040]],["moveId"]=30470,["seriesId"]=15},["150041"]={["action"]=[[只见$N扬身向前，使出一式「$M」，左右爪分别上劈下劈，呈雨水互补之势，随即身体跃至空中，双爪一齐攻向$n的$l。]],["id"]=[[150041]],["moveId"]=30480,["seriesId"]=15},["150042"]={["action"]=[[只见$N扬身向前，使出一式「$M」，左右爪分别上劈下劈，呈雨水互补之势，随即身体跃至空中，双爪一齐攻向$n的$l。]],["id"]=[[150042]],["moveId"]=30490,["seriesId"]=15},["150043"]={["action"]=[[$N使出一招「$M」，飞身上前，双爪分别下劈连上劈，随即身体跃空，双爪化出满天爪影，如天雨散落，攻向$n的$l。]],["id"]=[[150043]],["moveId"]=30500,["seriesId"]=15},["150044"]={["action"]=[[$N一跃而起，一式「$M」双爪交替出击，上劈连下劈，爪力浩荡，身体乘风凌空，双爪朝下，宛若雨幕一般罩向$n的$l。]],["id"]=[[150044]],["moveId"]=30510,["seriesId"]=15},["15005"]={["action"]=[[$N使出一招「$M」，单爪运劲下劈，仿若天河降落，横扫$n的$l。]],["id"]=[[15005]],["moveId"]=30060,["seriesId"]=15},["15006"]={["action"]=[[$N跃至半空，一招「$M」单爪下劈，如洪水般罩向$n的$l。]],["id"]=[[15006]],["moveId"]=30070,["seriesId"]=15},["15007"]={["action"]=[[$N跃身跳起，身影在空中来回闪现，像水般无定形，一招「$M」声东击西，单爪上攻直击$n的$l。]],["id"]=[[15007]],["moveId"]=30080,["seriesId"]=15},["15008"]={["action"]=[[$N跃至半空，一招「$M」双爪急出，如洪水般罩向$n的$l。]],["id"]=[[15008]],["moveId"]=30100,["seriesId"]=15},["15009"]={["action"]=[[$N跃身跳起，身影在空中来回闪现，像水般无定形，一招「$M」声东击西，单爪上攻直击$n的$l。]],["id"]=[[15009]],["moveId"]=30110,["seriesId"]=15},["16001"]={["action"]=[[$N指如疾风利刃，单指直刺而出，匆匆点向$n的$l，正是一招「$M」。]],["id"]=[[16001]],["moveId"]=40010,["seriesId"]=16},["160010"]={["action"]=[[$N双手抱圆，道道冷风聚于手中，蓦然二指击出，几缕指风飞袭$n的$l，看似无力，实是无坚不摧。正是一招「$M」。]],["id"]=[[160010]],["moveId"]=40220,["seriesId"]=16},["160011"]={["action"]=[[$N左右手曲起食指，两侧击出，只听嗤嗤声响，两指宛如两支疾风劲矢，射向$n的$l。正是一招「$M」。]],["id"]=[[160011]],["moveId"]=40250,["seriesId"]=16},["160012"]={["action"]=[[$N冷冷一笑，双指错落搭置，须臾间$N双指化为风刃，一招「$M」凶狠地向$n的$l刺去。]],["id"]=[[160012]],["moveId"]=40270,["seriesId"]=16},["160013"]={["action"]=[[$N一招「$M」，轻笑一声，双手尾指交叉，指端激出两道惊人指力，疾风激荡，掠向$n$l。]],["id"]=[[160013]],["moveId"]=40290,["seriesId"]=16},["160014"]={["action"]=[[$N伸出两指，弹指有声，突见两道指力由指尖透出，好似一场瑟瑟寒风，一招「$M」射向$n的$l。]],["id"]=[[160014]],["moveId"]=40320,["seriesId"]=16},["160015"]={["action"]=[[$N双指并拢，和身而上，左右手一前一后戳向$n的$l，似是风卷残云。正是一招「$M」。]],["id"]=[[160015]],["moveId"]=40340,["seriesId"]=16},["160016"]={["action"]=[[$N向$n的$l连点数指，劲风更激起无数尖啸之声，这招「$M」一出风声四起，难以设防。]],["id"]=[[160016]],["moveId"]=40360,["seriesId"]=16},["160017"]={["action"]=[[$N淡淡微笑，双手交互轮划，风中卓然衣袂飘然，双手对着$n的$l轻轻弹出，指力顺风漫卷而来。正是一招「$M」。]],["id"]=[[160017]],["moveId"]=40390,["seriesId"]=16},["160018"]={["action"]=[[只见$N四周冷风激荡，须臾间似乎融身入风，身影捉摸不定，双手连挥，指尖破风而至，攻向$n的$l。正是一招「$M」。]],["id"]=[[160018]],["moveId"]=40410,["seriesId"]=16},["160019"]={["action"]=[[$N双指并拢虚点而出，合「$M」为一式，只闻风声呼啸，须臾间一股罡风直射$n的$l。]],["id"]=[[160019]],["moveId"]=40430,["seriesId"]=16},["16002"]={["action"]=[[只听$N一声冷笑，指尖上聚气丝丝冷