={["action"]=[[$N猛踢一脚，随后倒立出腿。腿势越踢越快，向$n的$l一波接着一波攻去，犹如春风来去不息。正是一招「$M」。]],["id"]=[[210048]],["moveId"]=50310,["seriesId"]=21},["210049"]={["action"]=[[只听一声风吼，大风夹杂着腿影呼啸而来，风影中隐约能见$N身影随风翻飞，数腿直击$n的$l。正是一招「$M」。]],["id"]=[[210049]],["moveId"]=50310,["seriesId"]=21},["21005"]={["action"]=[[$N收左手，右手原地向前架在地面，右脚顺势向$n的$l直踢而出，弹腿疾如惊风，正是一式「$M」。]],["id"]=[[21005]],["moveId"]=50060,["seriesId"]=21},["210050"]={["action"]=[[只见$N先是一记直踢，后接倒立双腿，形若旋风飞沙走石，直击$n的$l，誓要将$n葬于其中。正是一招「$M」。]],["id"]=[[210050]],["moveId"]=50320,["seriesId"]=21},["210051"]={["action"]=[[$N猛踢一脚，随后倒立出腿。腿势越踢越快，向$n的$l一波接着一波攻去，犹如春风来去不息。正是一招「$M」。]],["id"]=[[210051]],["moveId"]=50320,["seriesId"]=21},["210052"]={["action"]=[[只听一声风吼，大风夹杂着腿影呼啸而来，风影中隐约能见$N身影随风翻飞，数腿直击$n的$l。正是一招「$M」。]],["id"]=[[210052]],["moveId"]=50320,["seriesId"]=21},["210053"]={["action"]=[[只见$N先是一记直踢，后接倒立双腿，形若旋风飞沙走石，直击$n的$l，誓要将$n葬于其中。正是一招「$M」。]],["id"]=[[210053]],["moveId"]=50330,["seriesId"]=21},["210054"]={["action"]=[[$N猛踢一脚，随后倒立出腿。腿势越踢越快，向$n的$l一波接着一波攻去，犹如春风来去不息。正是一招「$M」。]],["id"]=[[210054]],["moveId"]=50330,["seriesId"]=21},["210055"]={["action"]=[[只听一声风吼，大风夹杂着腿影呼啸而来，风影中隐约能见$N身影随风翻飞，数腿直击$n的$l。正是一招「$M」。]],["id"]=[[210055]],["moveId"]=50330,["seriesId"]=21},["210056"]={["action"]=[[$N右脚凌空，晃出一片腿影，霎那间向$n的$l一连踢出三脚，$n只觉刮起一场料峭寒风，令人遍体生寒。正是一招「$M」。]],["id"]=[[210056]],["moveId"]=50340,["seriesId"]=21},["210057"]={["action"]=[[$N大踏步向前，向着$n上中下三路连出三腿，腿如疾风，声势浩荡，直逼$n的$l。正是一招「$M」。]],["id"]=[[210057]],["moveId"]=50350,["seriesId"]=21},["210058"]={["action"]=[[$N低吼一声，随风而动，曲腿将足尖反点，一式「$M」踢出，卷起片片腿风击向$n的$l。]],["id"]=[[210058]],["moveId"]=50370,["seriesId"]=21},["210059"]={["action"]=[[$N步脚下虚浮，步伐渐乱，身形忽倒忽跳，犹如一个醉汉在风中嬉戏，足下随心更随风，飘飘渺渺踢向$n的$l。]],["id"]=[[210059]],["moveId"]=50380,["seriesId"]=21},["21006"]={["action"]=[[只见$N倒立出腿，两腿齐踢带起道道腿风，腿风夹杂着罡风向$n的$l倒灌而去。正是一招「$M」。]],["id"]=[[21006]],["moveId"]=50070,["seriesId"]=21},["210060"]={["action"]=[[$N神色自若，漠然抢进$n攻势中，时而倒踢腿，时而跳起踢腿，身如卷入飓风的落叶，不断攻向$n的$l。正是一招「$M」。]],["id"]=[[210060]],["moveId"]=50390,["seriesId"]=21},["210061"]={["action"]=[[风尘前后起，飞踏上下来，只见$N追风而动，身形上下翻飞，时不时踏出一脚击向$n的$l。正是一招「$M」。]],["id"]=[[210061]],["moveId"]=50400,["seriesId"]=21},["210062"]={["action"]=[[$N前踏三步，踢出三脚，腿影随风摇曳，令人难辨虚实，风声鹤唳间直取$n的$l。正是一招「$M」。]],["id"]=[[210062]],["moveId"]=50410,["seriesId"]=21},["210063"]={["action"]=[[$N前踏三步，踢出三脚，腿影随风摇曳，令人难辨虚实，风声鹤唳间直取$n的$l。正是一招「$M」。]],["id"]=[[210063]],["moveId"]=50420,["seriesId"]=21},["210064"]={["action"]=[[只见$N身形化作一团飓风，朝着$n飞掠而去，漫天腿影直击$n的$l，令$n只觉无处可逃。正是一招「$M」。]],["id"]=[[210064]],["moveId"]=50430,["seriesId"]=21},["210065"]={["action"]=[[只见$N身形化作一团飓风，朝着$n飞掠而去，漫天腿影直击$n的$l，令$n只觉无处可逃。正是一招「$M」。]],["id"]=[[210065]],["moveId"]=50440,["seriesId"]=21},["210066"]={["action"]=[[只见$N手一撑地，顿时腿风滔滔，将$n的$l笼罩其内，$n只觉四处风起，不寒而栗。正是一招「$M」。]],["id"]=[[210066]],["moveId"]=50450,["seriesId"]=21},["210067"]={["action"]=[[只见$N倒起身子，以腿作刃，化作一件人形兵器直击$n的$l，所到之处宛如劲风拔草，寸草不生。正是一招「$M」。]],["id"]=[[210067]],["moveId"]=50460,["seriesId"]=21},["210068"]={["action"]=[[突见$N出招快如惊风，倒起连踢，跳起又踢，首尾来回腾转，腿风苍苍直卷$n的$l，让$n闻风而逃。正是一招「$M」。]],["id"]=[[210068]],["moveId"]=50460,["seriesId"]=21},["210069"]={["action"]=[[$N倒立出腿，声势浩大却是兴风作浪，诱敌深入，蓦然间一记弹跳飞踢直攻$n的$l，才是真正捕风捉影。正是一招「$M」。]],["id"]=[[210069]],["moveId"]=50460,["seriesId"]=21},["21007"]={["action"]=[[$N飞身而起，身形扭作一团旋风，双腿在空中盘旋踢出，一式「$M」袭向$n的$l。]],["id"]=[[21007]],["moveId"]=50080,["seriesId"]=21},["210070"]={["action"]=[[只见$N倒起身子，以腿作刃，化作一件人形兵器直击$n的$l，所到之处宛如劲风拔草，寸草不生。正是一招「$M」。]],["id"]=[[210070]],["moveId"]=50470,["seriesId"]=21},["210071"]={["action"]=[[突见$N出招快如惊风，倒起连踢，跳起又踢，首尾来回腾转，腿风苍苍直卷$n的$l，让$n闻风而逃。正是一招「$M」。]],["id"]=[[210071]],["moveId"]=50470,["seriesId"]=21},["210072"]={["action"]=[[$N倒立出腿，声势浩大却是兴风作浪，诱敌深入，蓦然间一记弹跳飞踢直攻$n的$l，才是真正捕风捉影。正是一招「$M」。]],["id"]=[[210072]],["moveId"]=50470,["seriesId"]=21},["210073"]={["action"]=[[只见$N倒起身子，以腿作刃，化作一件人形兵器直击$n的$l，所到之处宛如劲风拔草，寸草不生。正是一招「$M」。]],["id"]=[[210073]],["moveId"]=50480,["seriesId"]=21},["210074"]={["action"]=[[突见$N出招快如惊风，倒起连踢，跳起又踢，首尾来回腾转，腿风苍苍直卷$n的$l，让$n闻风而逃。正是一招「$M」。]],["id"]=[[210074]],["moveId"]=50480,["seriesId"]=21},["210075"]={["action"]=[[$N倒立出腿，声势浩大却是兴风作浪，诱敌深入，蓦然间一记弹跳飞踢直攻$n的$l，才是真正捕风捉影。正是一招「$M」。]],["id"]=[[210075]],["moveId"]=50480,["seriesId"]=21},["210076"]={["action"]=[[只见$N倒起身子，以腿作刃，化作一件人形兵器直击$n的$l，所到之处宛如劲风拔草，寸草不生。正是一招「$M」。]],["id"]=[[210076]],["moveId"]=50490,["seriesId"]=21},["210077"]={["action"]=[[突见$N出招快如惊风，倒起连踢，跳起又踢，首尾来回腾转，腿风苍苍直卷$n的$l，让$n闻风而逃。正是一招「$M」。]],["id"]=[[210077]],["moveId"]=50490,["seriesId"]=21},["210078"]={["action"]=[[$N倒立出腿，声势浩大却是兴风作浪，诱敌深入，蓦然间一记弹跳飞踢直攻$n的$l，才是真正捕风捉影。正是一招「$M」。]],["id"]=[[210078]],["moveId"]=50490,["seriesId"]=21},["210079"]={["action"]=[[只见漫天人影闪烁，腿势如暴风肆虐，要将草木摧折，直击$n的$l。正是一招「$M」。]],["id"]=[[210079]],["moveId"]=50500,["seriesId"]=21},["21008"]={["action"]=[[$N一转身，反身飞跃而起起，以旋风之势向$n的$l踢出数腿，快得连腿影都看不清。正是一招「$M」。]],["id"]=[[21008]],["moveId"]=50080,["seriesId"]=21},["210080"]={["action"]=[[$N疾风前行，右脚迈出左脚正蹬，左脚迈出右脚怒踏，迅捷而敏锐，似风中藏着一枚暗针，直取$n的$l。正是一招「$M」。]],["id"]=[[210080]],["moveId"]=50510,["seriesId"]=21},["21009"]={["action"]=[[$N突然跃起，双足连环圈转，一式「$M」踢出，足尖带风，风裹泥尘攻向$n的$l。]],["id"]=[[21009]],["moveId"]=50080,["seriesId"]=21},["22001"]={["action"]=[[平地扬尘，黄沙漫卷，只见$N呼啸而来，人影好似一只嗜血猛虎，冲到$n面前怒踏$n的$l。正是一招「$M」。]],["id"]=[[22001]],["moveId"]=50010,["seriesId"]=22},["220010"]={["action"]=[[$N高高一跃，凌空倒挂，蓦然间两腿凭空剪下，好似一双虎尾来回抽打，左右袭向$n的$l。正是一招「$M」。]],["id"]=[[220010]],["moveId"]=50090,["seriesId"]=22},["220011"]={["action"]=[[$N凌空一纵，身形有若虎王跃向山头，在半空倒挂悬停，双腿划出两道圆弧，直击$n的$l。正是一招「$M」。]],["id"]=[[220011]],["moveId"]=50090,["seriesId"]=22},["220012"]={["action"]=[[$N足下一点，跃到$n上空，猛然间两腿倒卷而下，攻势如恶虎衔羊，直击$n的$l。正是一招「$M」。]],["id"]=[[220012]],["moveId"]=50090,["seriesId"]=22},["220013"]={["action"]=[[$N高高一跃，凌空倒挂，蓦然间两腿凭空剪下，好似一双虎尾来回抽打，左右袭向$n的$l。正是一招「$M」。]],["id"]=[[220013]],["moveId"]=50100,["seriesId"]=22},["220014"]={["action"]=[[$N凌空一纵，身形有若虎王跃向山头，在半空倒挂悬停，双腿划出两道圆弧，直击$n的$l。正是一招「$M」。]],["id"]=[[220014]],["moveId"]=50100,["seriesId"]=22},["220015"]={["action"]=[[$N足下一点，跃到$n上空，猛然间两腿倒卷而下，攻势如恶虎衔羊，直击$n的$l。正是一招「$M」。]],["id"]=[[220015]],["moveId"]=50100,["seriesId"]=22},["220016"]={["action"]=[[$N高高一跃，凌空倒挂，蓦然间两腿凭空剪下，好似一双虎尾来回抽打，左右袭向$n的$l。正是一招「$M」。]],["id"]=[[220016]],["moveId"]=50110,["seriesId"]=22},["220017"]={["action"]=[[$N凌空一纵，身形有若虎王跃向山头，在半空倒挂悬停，双腿划出两道圆弧，直击$n的$l。正是一招「$M」。]],["id"]=[[220017]],["moveId"]=50110,["seriesId"]=22},["220018"]={["action"]=[[$N足下一点，跃到$n上空，猛然间两腿倒卷而下，攻势如恶虎衔羊，直击$n的$l。正是一招「$M」。]],["id"]=[[220018]],["moveId"]=50110,["seriesId"]=22},["220019"]={["action"]=[[人影疾走，虎啸连连，只见$N连环踢腿，仿佛是恶虎扑了又扑，直取$n的$l。正是一招「$M」。]],["id"]=[[220019]],["moveId"]=50120,["seriesId"]=22},["22002"]={["action"]=[[只听$N一声虎吼，赫然扫出一记低鞭腿，似是虎尾一剪一荡，直击$n的$l，满地枯叶一扫而空。正是一招「$M」。]],["id"]=[[22002]],["moveId"]=50030,["seriesId"]=22},["220020"]={["action"]=[[只见地面劲风猎猎，草叶翻飞，竟是$N低扫两腿，攻向$n的$l，好似虎尾来回扫荡。正是一招「$M」。]],["id"]=[[220020]],["moveId"]=50130,["seriesId"]=22},["220021"]={["action"]=[[$N一记直踢接上踢，出腿刚猛无匹，似是老虎上下扑击，直取$n的$l。正是一招「$M」。]],["id"]=[[220021]],["moveId"]=50140,["seriesId"]=22},["220022"]={["action"]=[[$N一记直踢接下踢，出腿所向披靡，似是恶虎扑击要害，直取$n的$l。正是一招「$M」。]],["id"]=[[220022]],["moveId"]=50150,["seriesId"]=22},["220023"]={["action"]=[[$N一记直踢接下踢，出腿所向披靡，似是恶虎扑击要害，直取$n的$l。正是一招「$M」。]],["id"]=[[220023]],["moveId"]=50160,["seriesId"]=22},["220024"]={["action"]=[[须臾间$N倒立而起，出腿连连，$n只觉一只恶虎人立而起，欲将$n的$l碾碎成泥。正是一招「$M」。]],["id"]=[[220024]],["moveId"]=50170,["seriesId"]=22},["220025"]={["action"]=[[$N先踢一脚，随后向前一倒，倒立连踢，仿佛猛虎扑空，顺势身形翻转，又取$n的$l。正是一招「$M」。]],["id"]=[[220025]],["moveId"]=50180,["seriesId"]=22},["220026"]={["action"]=[[$N先踢一脚，随后向前一倒，倒立连踢，仿佛猛虎扑空，顺势身形翻转，又取$n的$l。正是一招「$M」。]],["id"]=[[220026]],["moveId"]=50200,["seriesId"]=22},["220027"]={["action"]=[[只见黑影暴掠，宛若黑虎见猎扑击，霎那间$N踢腿连连，攻向$n的$l。正是一招「$M」。]],["id"]=[[220027]],["moveId"]=50210,["seriesId"]=22},["220028"]={["action"]=[[只见黑影暴掠，宛若黑虎见猎扑击，霎那间$N踢腿连连，攻向$n的$l。正是一招「$M」。]],["id"]=[[220028]],["moveId"]=50220,["seriesId"]=22},["220029"]={["action"]=[[$N虎掌一撑，倒立而起，双腿连连踢出，似是虎尾漫卷而来，直逼$n的$l。正是一招「$M」。]],["id"]=[[220029]],["moveId"]=50230,["seriesId"]=22},["22003"]={["action"]=[[只听$N一声虎吼，赫然扫出一记低鞭腿，似是虎尾一剪一荡，直击$n的$l，满地枯叶一扫而空。正是一招「$M」。]],["id"]=[[22003]],["moveId"]=50040,["seriesId"]=22},["220030"]={["action"]=[[$N倒立出腿，一双腿状若巨虎獠牙，反复钳向$n的$l，进退间$n真如羊入虎口。正是一招「$M」。]],["id"]=[[220030]],["moveId"]=50240,["seriesId"]=22},["220031"]={["action"]=[[$N翻身倒转，头下脚上，猛然间连出双腿，似是群虎爬山到处来袭，攻向$n的$l。正是一招「$M」。]],["id"]=[[220031]],["moveId"]=50250,["seriesId"]=22},["220032"]={["action"]=[[$N倒转身形，以手撑地，腿在上方频频踢出，霎时间腿影重重，虎啸山林般攻向$n的$l。正是一招「$M」。]],["id"]=[[220032]],["moveId"]=50260,["seriesId"]=22},["220033"]={["action"]=[[$N倒施逆行，头在下脚在上，一时间腿影重重攻向$n的$l，$n如入虎穴，不知该如何抵挡。正是一招「$M」。]],["id"]=[[220033]],["moveId"]=50260,["seriesId"]=22},["220034"]={["action"]=[[$N如怪虎伏腰，倒立行走，行进间两个后腿不断踢向$n的$l，让$n错愕不已。正是一招「$M」。]],["id"]=[[220034]],["moveId"]=50260,["seriesId"]=22},["220035"]={["action"]=[[$N倒转身形，以手撑地，腿在上方频频踢出，霎时间腿影重重，虎啸山林般攻向$n的$l。正是一招「$M」。]],["id"]=[[220035]],["moveId"]=50270,["seriesId"]=22},["220036"]={["action"]=[[$N倒施逆行，头在下脚在上，一时间腿影重重攻向$n的$l，$n如入虎穴，不知该如何抵挡。正是一招「$M」。]],["id"]=[[220036]],["moveId"]=50270,["seriesId"]=22},["220037"]={["action"]=[[$N如怪虎伏腰，倒立行走，行进间两个后腿不断踢向$n的$l，让$n错愕不已。正是一招「$M」。]],["id"]=[[220037]],["moveId"]=50270,["seriesId"]=22},["220038"]={["action"]=[[$N倒转身形，以手撑地，腿在上方频频踢出，霎时间腿影重重，虎啸山林般攻向$n的$l。正是一招「$M」。]],["id"]=[[220038]],["moveId"]=50280,["seriesId"]=22},["220039"]={["action"]=[[$N倒施逆行，头在下脚在上，一时间腿影重重攻向$n的$l，$n如入虎穴，不知该如何抵挡。正是一招「$M」。]],["id"]=[[220039]],["moveId"]=50280,["seriesId"]=22},["22004"]={["action"]=[[$N突出一腿，直勾勾踢向$n的$l，又快又狠，似是一只饥饿已久的老虎，见猎扑食。正是一招「$M」。]],["id"]=[[22004]],["moveId"]=50050,["seriesId"]=22},["220040"]={["action"]=[[$N如怪虎伏腰，倒立行走，行进间两个后腿不断踢向$n的$l，让$n错愕不已。正是一招「$M」。]],["id"]=[[220040]],["moveId"]=50280,["seriesId"]=22},["220041"]={["action"]=[[$N倒转身形，以手撑地，腿在上方频频踢出，霎时间腿影重重，虎啸山林般攻向$n的$l。正是一招「$M」。]],["id"]=[[220041]],["moveId"]=50290,["seriesId"]=22},["220042"]={["action"]=[[$N倒施逆行，头在下脚在上，一时间腿影重重攻向$n的$l，$n如入虎穴，不知该如何抵挡。正是一招「$M」。]],["id"]=[[220042]],["moveId"]=50290,["seriesId"]=22},["220043"]={["action"]=[[$N如怪虎伏腰，倒立行走，行进间两个后腿不断踢向$n的$l，让$n错愕不已。正是一招「$M」。]],["id"]=[[220043]],["moveId"]=50290,["seriesId"]=22},["220044"]={["action"]=[[只见$N先是一记直踢，后接倒立双腿，形若饿虎飞扑甩尾，誓要将$n粉身碎骨。正是一招「$M」。]],["id"]=[[220044]],["moveId"]=50300,["seriesId"]=22},["220045"]={["action"]=[[$N猛踢一脚，随后倒立出腿，腿势越踢越快，向$n的$l攻去。恍惚间$n只觉面前竟是一只吊睛猛虎。正是一招「$M」。]],["id"]=[[220045]],["moveId"]=50300,["seriesId"]=22},["220046"]={["action"]=[[只听$N虎啸一声，身形上下闪转腾挪，好似虎跃山涧，时机一到两腿即刻踢出。正是一招「$M」。]],["id"]=[[220046]],["moveId"]=50300,["seriesId"]=22},["220047"]={["action"]=[[只见$N先是一记直踢，后接倒立双腿，形若饿虎飞扑甩尾，誓要将$n粉身碎骨。正是一招「$M」。]],["id"]=[[220047]],["moveId"]=50310,["seriesId"]=22},["220048"]={["action"]=[[$N猛踢一脚，随后倒立出腿，腿势越踢越快，向$n的$l攻去。恍惚间$n只觉面前竟是一只吊睛猛虎。正是一招「$M」。]],["id"]=[[220048]],["moveId"]=50310,["seriesId"]=22},["220049"]={["action"]=[[只听$N虎啸一声，身形上下闪转腾挪，好似虎跃山涧，时机一到两腿即刻踢出。正是一招「$M」。]],["id"]=[[220049]],["moveId"]=50310,["seriesId"]=22},["22005"]={["action"]=[[只见$N翻身倒立飞出一脚，踢向$n的$l，身形宛若白虎嬉戏，动作当真潇洒自如。正是一招「$M」。]],["id"]=[[22005]],["moveId"]=50060,["seriesId"]=22},["220050"]={["action"]=[[只见$N先是一记直踢，后接倒立双腿，形若饿虎飞扑甩尾，誓要将$n粉身碎骨。正是一招「$M」。]],["id"]=[[220050]],["moveId"]=50320,["seriesId"]=22},["220051"]={["action"]=[[$N猛踢一脚，随后倒立出腿，腿势越踢越快，向$n的$l攻去。恍惚间$n只觉面前竟是一只吊睛猛虎。正是一招「$M」。]],["id"]=[[220051]],["moveId"]=50320,["seriesId"]=22},["220052"]={["action"]=[[只听$N虎啸一声，身形上下闪转腾挪，好似虎跃山涧，时机一到两腿即刻踢出。正是一招「$M」。]],["id"]=[[220052]],["moveId"]=50320,["seriesId"]=22},["220053"]={["action"]=[[只见$N先是一记直踢，后接倒立双腿，形若饿虎飞扑甩尾，誓要将$n粉身碎骨。正是一招「$M」。]],["id"]=[[220053]],["moveId"]=50330,["seriesId"]=22},["220054"]={["action"]=[[$N猛踢一脚，随后倒立出腿，腿势越踢越快，向$n的$l攻去。恍惚间$n只觉面前竟是一只吊睛猛虎。正是一招「$M」。]],["id"]=[[220054]],["moveId"]=50330,["seriesId"]=22},["220055"]={["action"]=[[只听$N虎啸一声，身形上下闪转腾挪，好似虎跃山涧，时机一到两腿即刻踢出。正是一招「$M」。]],["id"]=[[220055]],["moveId"]=50330,["seriesId"]=22},["220056"]={["action"]=[[只见$N摆腿上踢连环，踢出道道弧线直击$n的$l，似是一头恶虎准备噬人。正是一招「$M」。]],["id"]=[[220056]],["moveId"]=50340,["seriesId"]=22},["220057"]={["action"]=[[$n只听破空之声在耳边炸响，原是$N扫腿不绝，似是猛虎抽尾，势大力沉击向$n的$l。正是一招「$M」。]],["id"]=[[220057]],["moveId"]=50350,["seriesId"]=22},["220058"]={["action"]=[[$N瞳孔一缩，一对虎目精芒暴涨，单腿直直踢出，腿影中虚虚实实，藏龙卧虎，随时会将$n的$l击穿。正是一招「$M」。]],["id"]=[[220058]],["moveId"]=50370,["seriesId"]=22},["220059"]={["action"]=[[$N神色自若，漠然抢进$n攻势中，顶着来击时而倒踢腿，时而跳起踢腿，直取$n的$l，誓要虎口拔牙。正是一招「$M」。]],["id"]=[[220059]],["moveId"]=50380,["seriesId"]=22},["22006"]={["action"]=[[须臾间$N双手撑地，头下脚上，两腿猛然弹出，仿佛是两肋插翅的猛虎，狂攻$n的$l。正是一招「$M」。]],["id"]=[[22006]],["moveId"]=50070,["seriesId"]=22},["220060"]={["action"]=[[只见$N身形翻腾不绝，腿势不断送出，连连踢向$n的$l，似是一只被困已久的饿虎开关出柙。正是一招「$M」。]],["id"]=[[220060]],["moveId"]=50390,["seriesId"]=22},["220061"]={["action"]=[[只觉$N倒踢飞踢，不断攻向$n的$l，腿招化作一张虎面有须有牙，真真假假，让$n不敢轻易捋其虎须。正是一招「$M」。]],["id"]=[[220061]],["moveId"]=50400,["seriesId"]=22},["220062"]={["action"]=[[$N大喝一声，猛然摆腿上下齐踢，腿势不断狂攻$n的$l，当真是暴虎冯河，蛮不讲理。正是一招「$M」。]],["id"]=[[220062]],["moveId"]=50410,["seriesId"]=22},["220063"]={["action"]=[[$N大喝一声，猛然摆腿上下齐踢，腿势不断狂攻$n的$l，当真是暴虎冯河，蛮不讲理。正是一招「$M」。]],["id"]=[[220063]],["moveId"]=50420,["seriesId"]=22},["220064"]={["action"]=[[恍惚间只见$N三段连踢，一气呵成，霎那间由守转攻，似是一个猛虎连攻$n的$l，让$n只能虎口求生。正是一招「$M」。]],["id"]=[[220064]],["moveId"]=50430,["seriesId"]=22},["220065"]={["action"]=[[恍惚间只见$N三段连踢，一气呵成，霎那间由守转攻，似是一个猛虎连攻$n的$l，让$n只能虎口求生。正是一招「$M」。]],["id"]=[[220065]],["moveId"]=50440,["seriesId"]=22},["220066"]={["action"]=[[只见$N手一撑地，顿时腿影滔滔，呼啸连连，将$n的$l笼罩其内，一时间只觉$n已进猛虎深山。正是一招「$M」。]],["id"]=[[220066]],["moveId"]=50450,["seriesId"]=22},["220067"]={["action"]=[[只见$N倒起身子，以腿作刃，化作一件人形兵器直击$n的$l，所到之处宛如猛虎过境，鸡犬不留。正是一招「$M」。]],["id"]=[[220067]],["moveId"]=50460,["seriesId"]=22},["220068"]={["action"]=[[突见$N出招怪模怪样，倒起连踢，跳起又踢，好似野虎来回腾转，狂攻$n的$l，就是要让$n骑虎难下。正是一招「$M」。]],["id"]=[[220068]],["moveId"]=50460,["seriesId"]=22},["220069"]={["action"]=[[$N倒立出腿，声势浩大却是假虎张威，诱敌深入，蓦然间一记弹跳飞踢直取$n的$l，才是猛虎出闸。正是一招「$M」。]],["id"]=[[220069]],["moveId"]=50460,["seriesId"]=22},["22007"]={["action"]=[[$N高高一跃，凌空倒挂，蓦然间两腿凭空剪下，好似一双虎尾来回抽打，左右袭向$n的$l。正是一招「$M」。]],["id"]=[[22007]],["moveId"]=50080,["seriesId"]=22},["220070"]={["action"]=[[只见$N倒起身子，以腿作刃，化作一件人形兵器直击$n的$l，所到之处宛如猛虎过境，鸡犬不留。正是一招「$M」。]],["id"]=[[220070]],["moveId"]=50470,["seriesId"]=22},["220071"]={["action"]=[[突见$N出招怪模怪样，倒起连踢，跳起又踢，好似野虎来回腾转，狂攻$n的$l，就是要让$n骑虎难下。正是一招「$M」。]],["id"]=[[220071]],["moveId"]=50470,