"]=[[240024]],["moveId"]=50170,["seriesId"]=24},["240025"]={["action"]=[[$N先踢一脚，随后向前一倒倒立连踢，仿佛天河倒挂，随后顺势身形翻转，又取$n的$l。正是一招「$M」。]],["id"]=[[240025]],["moveId"]=50180,["seriesId"]=24},["240026"]={["action"]=[[$N先踢一脚，随后向前一倒倒立连踢，仿佛天河倒挂，随后顺势身形翻转，又取$n的$l。正是一招「$M」。]],["id"]=[[240026]],["moveId"]=50200,["seriesId"]=24},["240027"]={["action"]=[[只见$N人影飞掠，好似江底嬉戏的游鱼，霎那间$N踢腿连连，攻向$n的$l。正是一招「$M」。]],["id"]=[[240027]],["moveId"]=50210,["seriesId"]=24},["240028"]={["action"]=[[只见$N人影飞掠，好似江底嬉戏的游鱼，霎那间$N踢腿连连，攻向$n的$l。正是一招「$M」。]],["id"]=[[240028]],["moveId"]=50220,["seriesId"]=24},["240029"]={["action"]=[[$N单掌一撑，倒立而起，双腿连连踢出，似是一团江浪奔腾咆哮而来，直逼$n的$l。正是一招「$M」。]],["id"]=[[240029]],["moveId"]=50230,["seriesId"]=24},["24003"]={["action"]=[[$N左腿支地，右腿踢出如奔腾的大江，一时间怒涛骇浪，直击$n的$l。正是一招「$M」。]],["id"]=[[24003]],["moveId"]=50040,["seriesId"]=24},["240030"]={["action"]=[[$N倒立出腿，一双腿状若涓流汇聚成河，反复罩向$n的$l，进退间$n真如身置江中，随波逐流。正是一招「$M」。]],["id"]=[[240030]],["moveId"]=50240,["seriesId"]=24},["240031"]={["action"]=[[$N翻身倒转，头下脚上，猛然间连出双腿，似是江河湍急，波澜起伏到处来袭，攻向$n的$l。正是一招「$M」。]],["id"]=[[240031]],["moveId"]=50250,["seriesId"]=24},["240032"]={["action"]=[[$N倒转身形，以手撑地，腿在上方频频踢出，霎时间腿影重重，宛如江河翻滚，攻向$n的$l。正是一招「$M」。]],["id"]=[[240032]],["moveId"]=50260,["seriesId"]=24},["240033"]={["action"]=[[$N倒施逆行，俯身挺地如锦鲤投江，倒转踢腿更似翻江倒海，招招直攻$n的$l。正是一招「$M」。]],["id"]=[[240033]],["moveId"]=50260,["seriesId"]=24},["240034"]={["action"]=[[只见$N倒过身形，眨眼间两腿频频攻下，化作一场江浪排空，攻向$n的$l。正是一招「$M」。]],["id"]=[[240034]],["moveId"]=50260,["seriesId"]=24},["240035"]={["action"]=[[$N倒转身形，以手撑地，腿在上方频频踢出，霎时间腿影重重，宛如江河翻滚，攻向$n的$l。正是一招「$M」。]],["id"]=[[240035]],["moveId"]=50270,["seriesId"]=24},["240036"]={["action"]=[[$N倒施逆行，俯身挺地如锦鲤投江，倒转踢腿更似翻江倒海，招招直攻$n的$l。正是一招「$M」。]],["id"]=[[240036]],["moveId"]=50270,["seriesId"]=24},["240037"]={["action"]=[[只见$N倒过身形，眨眼间两腿频频攻下，化作一场江浪排空，攻向$n的$l。正是一招「$M」。]],["id"]=[[240037]],["moveId"]=50270,["seriesId"]=24},["240038"]={["action"]=[[$N倒转身形，以手撑地，腿在上方频频踢出，霎时间腿影重重，宛如江河翻滚，攻向$n的$l。正是一招「$M」。]],["id"]=[[240038]],["moveId"]=50280,["seriesId"]=24},["240039"]={["act