"moveId"]=50320,["seriesId"]=24},["240053"]={["action"]=[[只见$N先是一记直踢，后接倒立双腿，腿势川流不息，似是一条长河向$n的$l奔涌而来。]],["id"]=[[240053]],["moveId"]=50330,["seriesId"]=24},["240054"]={["action"]=[[$N猛踢一脚，随后倒立出腿。腿势越踢越快，一浪接一浪攻向$n的$l，可谓奔流不息，江水不绝。正是一招「$M」。]],["id"]=[[240054]],["moveId"]=50330,["seriesId"]=24},["240055"]={["action"]=[[$N使一式「$M」，单腿凌空踢出，随即身体倒立落地，双腿若蜿蜒长河没入山川，连环攻向$n的$l。]],["id"]=[[240055]],["moveId"]=50330,["seriesId"]=24},["240056"]={["action"]=[[只见$N摆腿上踢连环，踢出道道弧线直击$n的$l，似是九曲黄河惊涛拍岸。正是一招「$M」。]],["id"]=[[240056]],["moveId"]=50340,["seriesId"]=24},["240057"]={["action"]=[[$N大踏步向前，向着$n上中下三路连出三腿，腿如江河，分化三川，直逼$n的$l。正是一招「$M」。]],["id"]=[[240057]],["moveId"]=50350,["seriesId"]=24},["240058"]={["action"]=[[$N运劲于右腿，有如河川奔流不止，似携千斤之力三连直踢，狂攻$n的$l。正是一招「$M」。]],["id"]=[[240058]],["moveId"]=50370,["seriesId"]=24},["240059"]={["action"]=[[$N神色自若，漠然抢进$n攻势中，时而倒踢腿，时而跳起踢腿，似是负石投河，一心决绝，直击$n的$l。正是一招「$M」。]],["id"]=[[240059]],["moveId"]=50380,["seriesId"]=24},["24006"]={["action"]=[[须臾间$N双手撑地，头下脚上，两腿铁箍般锁向$n的$l，仿佛是一道长江天堑。正是一招「$M」。]],["id"]=[[24006]],["moveId"]=50070,["seriesId"]=24},["240060"]={["action"]=[[只见$N身形翻腾不绝，腿势不断送出，似是一江沉静的江水，突然决堤而来，直击$n的$l。正是一招「$M」。]],["id"]=[[240060]],["moveId"]=50390,["seriesId"]=24},["240061"]={["action"]=[[$N催动内力，一招「$M」单掌撑地倒立，双腿带着江水滔滔之势压向$n，随即身体跃空，这般连续两次对准$n的$l踢去。]],["id"]=[[240061]],["moveId"]=50400,["seriesId"]=24},["240062"]={["action"]=[[$N脚步飞快冲刺，一式「$M」，上踢接下踢，瞬间又接上踢，动作身形若江燕河鱼，直击$n的$l。]],["id"]=[[240062]],["moveId"]=50410,["seriesId"]=24},["240063"]={["action"]=[[$N脚步飞快冲刺，一式「$M」，上踢接下踢，瞬间又接上踢，动作身形若江燕河鱼，直击$n的$l。]],["id"]=[[240063]],["moveId"]=50420,["seriesId"]=24},["240064"]={["action"]=[[$N双腿上踢接下踢，转而再接直踢，一式「$M」犹如深江暗涌般攻向$n的$l，腿影闪烁，令其防不胜防。]],["id"]=[[240064]],["moveId"]=50430,["seriesId"]=24},["240065"]={["action"]=[[$N双腿上踢接下踢，转而再接直踢，一式「$M」犹如深江暗涌般攻向$n的$l，腿影闪烁，令其防不胜防。]],["id"]=[[240065]],["moveId"]=50440,["seriesId"]=24},["240066"]={["action"]=[[$N狂啸一声，使出一招「$M」，身体倒立不动，单腿横扫，翻江搅海，接着双腿发如江浪，一浪浪向$n的$l踢去。]],["id"]=[[240066]],["moveId"]=50450,["seriesId"]=24},["240067"]={["action"