oveId"]=60220,["seriesId"]=26},["260033"]={["action"]=[[$N身形随风飘起，一式「$M」使出翻身跃起伏身下刺，随后顺着风势手中$w下指，疾刺$n的$l。]],["id"]=[[260033]],["moveId"]=60220,["seriesId"]=26},["260034"]={["action"]=[[$N身若轻风，飘至$n面前抢出一剑，趁此之势又是借风势扬起，再度舞出一剑，剑剑不离$n的$l。正是一招「$M」。]],["id"]=[[260034]],["moveId"]=60220,["seriesId"]=26},["260035"]={["action"]=[[$N微微一笑，动作身形好似一阵暖风，挥剑斜斜劈向$n的$l，随后手腕一拧又是一刺。正是一招「$M」。]],["id"]=[[260035]],["moveId"]=60230,["seriesId"]=26},["260036"]={["action"]=[[只听$N一声大喝，挥剑疾斩，剑刃逆风破障挥向$n的$l，谁知$N暗藏后手，一剑斩完又是一刺，正是一招「$M」。]],["id"]=[[260036]],["moveId"]=60240,["seriesId"]=26},["260037"]={["action"]=[[$N使出一式「$M」，闲庭信步举剑一劈一刺，只见剑光掠闪，剑芒仿佛在半空化成一股清风，向$n的$l穿透而来。]],["id"]=[[260037]],["moveId"]=60250,["seriesId"]=26},["260038"]={["action"]=[[$N手腕一抖，手中$w疾射而出，趁$n措手不及之际又复出一剑击向$n的$l，似飓风绝然不歇。正是一招「$M」。]],["id"]=[[260038]],["moveId"]=60260,["seriesId"]=26},["260039"]={["action"]=[[只见$w飞掷而出，顿时飞剑携风倒卷而来，紧接着$N疾步向前，一刺似凉风直透$n的$l，令人倒吸冷气。正是一招「$M」。]],["id"]=[[260039]],["moveId"]=60270,["seriesId"]=26},["26004"]={["action"]=[[只见$N一记「$M」，掣剑一跃，在空中扭转身形，头下脚上如凉风灌顶一般挥剑刺向$n的$l。]],["id"]=[[26004]],["moveId"]=60040,["seriesId"]=26},["260040"]={["action"]=[[眼前剑光疾驰闪过，竟是$w被$N掷出，随后$N身如附骨之风紧随其后，霎那间抬手接剑刺向$n的$l，正是一招「$M」。]],["id"]=[[260040]],["moveId"]=60280,["seriesId"]=26},["260041"]={["action"]=[[$N暗送巧劲，掷$w到$n面前，$w如松风穿林，掠而复返，$N随手接复又斩向$n的$l，令$n猝不及防。正是一招「$M」。]],["id"]=[[260041]],["moveId"]=60290,["seriesId"]=26},["260042"]={["action"]=[[$N前踏数步，惊风激荡，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，收剑而立，笑对狂风。正是一招「$M」。]],["id"]=[[260042]],["moveId"]=60300,["seriesId"]=26},["260043"]={["action"]=[[$N前踏数步，惊风激荡，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，收剑而立，笑对狂风。正是一招「$M」。]],["id"]=[[260043]],["moveId"]=60310,["seriesId"]=26},["260044"]={["action"]=[[此一招「$M」攻向$n的$l，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，身姿有若散云流风。]],["id"]=[[260044]],["moveId"]=60320,["seriesId"]=26},["260045"]={["action"]=[[此一招「$M」攻向$n的$l，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，身姿有若散云流风。]],["id"]=[[260045]],["moveId"]=60330,["seriesId"]=26},["260046"]={["action"]=[[$N振臂一扬，好似地上掀起大风，冲天而起，一招「$M」半空中挥剑连连，直斩$n的$l，剑光明灭骤起让人胆战心惊。]],["id"]=[[260046]],["moveId"]=60340,["seriesId"]=26},["260047"]={["action"]=[[$N振臂一扬，好似地上掀起大风，冲天而起，一招「$M」半空中挥剑连连，直斩$n的$l，剑光明灭骤起让人胆战心惊。]],["id"]=[[260047]],["moveId"]=60350,["seriesId"]=26},["260048"]={["action"]=[[$N岿然不动，须臾间$N一剑横斩先声夺人，剑势似有所阻，$N复出一剑又斩$n的$l，直叫阻势风吹云散。正是一招「$M」。]],["id"]=[[260048]],["moveId"]=60360,["seriesId"]=26},["260049"]={["action"]=[[$N似一团岚风，使一招「$M」，没入$n攻势之中，$N手腕一抖，手中$w来回直劈$n的$l，剑未及身却让$n大感切肤之痛。]],["id"]=[[260049]],["moveId"]=60370,["seriesId"]=26},["26005"]={["action"]=[[$N身形似一团旋风，跃上半空，而后手腕一抖剑带疾风，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[26005]],["moveId"]=60050,["seriesId"]=26},["260050"]={["action"]=[[$N突出一剑，剑如寒风穿透心口，而后身形流转，持剑冲天倒挂，剑锋直指$n的$l。正是一招「$M」。]],["id"]=[[260050]],["moveId"]=60380,["seriesId"]=26},["260051"]={["action"]=[[只见$w剑尖直颤，猛然刺向$n的$l，剑出顿时风行草偃，$N落上$n头顶破绽，提剑再刺，更似朗月清风。正是一招「$M」。]],["id"]=[[260051]],["moveId"]=60390,["seriesId"]=26},["260052"]={["action"]=[[$N出剑若疾风，剑尖一送却是点在$n的$l，突然剑招一改，风吟剑鸣合二为一，$w凌空一剑破空刺来。正是一招「$M」。]],["id"]=[[260052]],["moveId"]=60400,["seriesId"]=26},["260053"]={["action"]=[[$N闭目听风，捕风捉影，牢牢锁定$n气机，手中$w突然而发，一招「$M」使来直取$n的$l，剑势当真凌厉无匹。]],["id"]=[[260053]],["moveId"]=60410,["seriesId"]=26},["260054"]={["action"]=[[$N使一招「$M」，剑尖指地疾走数步，来到$n身前，只见$N振臂频挥，手中$w挥得白光连连，似风月流转，攻向$n的$l。]],["id"]=[[260054]],["moveId"]=60420,["seriesId"]=26},["260055"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记疾风跳斩，斩向$n的$l，当真是云散烈风，势不可挡。正是一招「$M」。]],["id"]=[[260055]],["moveId"]=60430,["seriesId"]=26},["260056"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记疾风跳斩，斩向$n的$l，当真是云散烈风，势不可挡。正是一招「$M」。]],["id"]=[[260056]],["moveId"]=60440,["seriesId"]=26},["260057"]={["action"]=[[$N运剑迅猛如风，挥动$w如栉风沐雨，节节劈向$n的$l，让$n难以招架。正是一招「$M」。]],["id"]=[[260057]],["moveId"]=60450,["seriesId"]=26},["260058"]={["action"]=[[只见$N一记「$M」身形直转，手中$w左右横斩，却是为最后一下兜头跳斩做下铺垫，真如一股穿堂风，朝$n的$l掠去。]],["id"]=[[260058]],["moveId"]=60460,["seriesId"]=26},["260059"]={["action"]=[[只见$N丝毫不歇，剑势如风萍浪迹，攻向$n的$l，左扫一剑，右斩一击，最后又是一记下劈斩。正是一招「$M」。]],["id"]=[[260059]],["moveId"]=60470,["seriesId"]=26},["26006"]={["action"]=[[$N身形似一团旋风，跃上半空，而后手腕一抖剑带疾风，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[26006]],["moveId"]=60060,["seriesId"]=26},["260060"]={["action"]=[[$N静如风平浪静，动若风起云涌，指间剑柄一旋，霎那间已经凌空劈出三剑，剑剑直取$n的$l。正是一招「$M」。]],["id"]=[[260060]],["moveId"]=60480,["seriesId"]=26},["260061"]={["action"]=[[$N持剑步若追风，直直逼到$n身前，抬手直刺横斩接下劈，剑剑不离$n的$l，势如风卷残云。正是一招「$M」。]],["id"]=[[260061]],["moveId"]=60490,["seriesId"]=26},["260062"]={["action"]=[[$N握剑而攻，使一招「$M」，剑招仿佛微风骤然变色，在$n的$l上一蛰即改，顿时大开大阖剑劈纵横，让$n倒吸一口凉气。]],["id"]=[[260062]],["moveId"]=60500,["seriesId"]=26},["260063"]={["action"]=[[猛然间$N身影闪烁不定，好似两肋生风，飞天遁地无处不在，一剑刺向$n的$l，角度刁钻让$n无法可想。正是一招「$M」。]],["id"]=[[260063]],["moveId"]=60510,["seriesId"]=26},["26007"]={["action"]=[[$N进退之间突然神色一凛，手中$w携疾风劲草之势横劈$n的$l，其剑势让$n自觉难以招架。正是一招「$M」。]],["id"]=[[26007]],["moveId"]=60070,["seriesId"]=26},["26008"]={["action"]=[[$N飞身跃起，祭出一式「$M」，$w震颤不绝发出一声风鸣之音，从半空中灌向$n的$l，真是势不可挡。]],["id"]=[[26008]],["moveId"]=60080,["seriesId"]=26},["26009"]={["action"]=[[$N一式「$M」，身形往前一探，只见白光一闪，利刃风断白云般斩向$n的$l。]],["id"]=[[26009]],["moveId"]=60090,["seriesId"]=26},["27001"]={["action"]=[[只见$N使出一记「$M」，手中$w化成一道匹练，直奔$n的$l而去，可谓心若猛虎，势如破竹。]],["id"]=[[27001]],["moveId"]=60010,["seriesId"]=27},["270010"]={["action"]=[[$N一式「$M」，身形往前一探，只见白光一闪，利刃恶虎扑羊般斩向$n的$l。]],["id"]=[[270010]],["moveId"]=60100,["seriesId"]=27},["270011"]={["action"]=[[$N手握$w须臾一斩，横空洒下一段剑光匹练，宛若白虎渡涧，直击$n的$l。正是一招「$M」。]],["id"]=[[270011]],["moveId"]=60110,["seriesId"]=27},["270012"]={["action"]=[[$N双腿一曲，身形弹射而起，持剑在半空中如虎扼羊喉，手中$w直直向$n劈下。正是一招「$M」。]],["id"]=[[270012]],["moveId"]=60120,["seriesId"]=27},["270013"]={["action"]=[[$N双腿一曲，身形弹射而起，持剑在半空中如虎扼羊喉，手中$w直直向$n劈下。正是一招「$M」。]],["id"]=[[270013]],["moveId"]=60130,["seriesId"]=27},["270014"]={["action"]=[[只见$N使出一式「$M」，手腕一震，$w顷刻投出。$w疾如脱闸之虎，携带破空之声飞向$n的$l。]],["id"]=[[270014]],["moveId"]=60140,["seriesId"]=27},["270015"]={["action"]=[[$N斜倚长剑，长啸而歌，却似虎王迟暮虽懒犹强，百无聊赖间$w自肋下翻刺而出，刺向$n的$l。正是一招「$M」。]],["id"]=[[270015]],["moveId"]=60150,["seriesId"]=27},["270016"]={["action"]=[[$N斜倚长剑，长啸而歌，却似虎王迟暮虽懒犹强，百无聊赖间$w自肋下翻刺而出，刺向$n的$l。正是一招「$M」。]],["id"]=[[270016]],["moveId"]=60160,["seriesId"]=27},["270017"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，剑剑不离$n的$l，出招迅猛如虎入羊群。]],["id"]=[[270017]],["moveId"]=60170,["seriesId"]=27},["270018"]={["action"]=[[$N擎剑冲向$n，先行跃起一剑，竟是虚招一晃调虎离山，随后抬手一剑刺向$n$l，要让这恶虎剑下伏诛。正是一招「$M」。]],["id"]=[[270018]],["moveId"]=60170,["seriesId"]=27},["270019"]={["action"]=[[$N手腕一震，抖出剑花平地空中各刺一剑，剑势刚直硬猛，剑招乱花迷眼，似是猛虎嬉戏。正是一招「$M」。]],["id"]=[[270019]],["moveId"]=60170,["seriesId"]=27},["27002"]={["action"]=[[$N使一招「$M」，突然身形暴涨，快若惊鸿，手中$w一摆似是猛虎荡尾而出，向$n的$l刺去。]],["id"]=[[27002]],["moveId"]=60020,["seriesId"]=27},["270020"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，剑剑不离$n的$l，出招迅猛如虎入羊群。]],["id"]=[[270020]],["moveId"]=60180,["seriesId"]=27},["270021"]={["action"]=[[$N擎剑冲向$n，先行跃起一剑，竟是虚招一晃调虎离山，随后抬手一剑刺向$n$l，要让这恶虎剑下伏诛。正是一招「$M」。]],["id"]=[[270021]],["moveId"]=60180,["seriesId"]=27},["270022"]={["action"]=[[$N手腕一震，抖出剑花平地空中各刺一剑，剑势刚直硬猛，剑招乱花迷眼，似是猛虎嬉戏。正是一招「$M」。]],["id"]=[[270022]],["moveId"]=60180,["seriesId"]=27},["270023"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，剑剑不离$n的$l，出招迅猛如虎入羊群。]],["id"]=[[270023]],["moveId"]=60190,["seriesId"]=27},["270024"]={["action"]=[[$N擎剑冲向$n，先行跃起一剑，竟是虚招一晃调虎离山，随后抬手一剑刺向$n$l，要让这恶虎剑下伏诛。正是一招「$M」。]],["id"]=[[270024]],["moveId"]=60190,["seriesId"]=27},["270025"]={["action"]=[[$N手腕一震，抖出剑花平地空中各刺一剑，剑势刚直硬猛，剑招乱花迷眼，似是猛虎嬉戏。正是一招「$M」。]],["id"]=[[270025]],["moveId"]=60190,["seriesId"]=27},["270026"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，剑剑不离$n的$l，出招迅猛如虎入羊群。]],["id"]=[[270026]],["moveId"]=60200,["seriesId"]=27},["270027"]={["action"]=[[$N擎剑冲向$n，先行跃起一剑，竟是虚招一晃调虎离山，随后抬手一剑刺向$n$l，要让这恶虎剑下伏诛。正是一招「$M」。]],["id"]=[[270027]],["moveId"]=60200,["seriesId"]=27},["270028"]={["action"]=[[$N手腕一震，抖出剑花平地空中各刺一剑，剑势刚直硬猛，剑招乱花迷眼，似是猛虎嬉戏。正是一招「$M」。]],["id"]=[[270028]],["moveId"]=60200,["seriesId"]=27},["270029"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，剑剑不离$n的$l，出招迅猛如虎入羊群。]],["id"]=[[270029]],["moveId"]=60210,["seriesId"]=27},["27003"]={["action"]=[[只见$N身形岿然不动，蓦然间神色一肃，手中$w夹杂着凌厉无匹的气势直指$n的$l，剑势仿佛猛虎出山。正是一招「$M」。]],["id"]=[[27003]],["moveId"]=60030,["seriesId"]=27},["270030"]={["action"]=[[$N擎剑冲向$n，先行跃起一剑，竟是虚招一晃调虎离山，随后抬手一剑刺向$n$l，要让这恶虎剑下伏诛。正是一招「$M」。]],["id"]=[[270030]],["moveId"]=60210,["seriesId"]=27},["270031"]={["action"]=[[$N手腕一震，抖出剑花平地空中各刺一剑，剑势刚直硬猛，剑招乱花迷眼，似是猛虎嬉戏。正是一招「$M」。]],["id"]=[[270031]],["moveId"]=60210,["seriesId"]=27},["270032"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，剑剑不离$n的$l，出招迅猛如虎入羊群。]],["id"]=[[270032]],["moveId"]=60220,["seriesId"]=27},["270033"]={["action"]=[[$N擎剑冲向$n，先行跃起一剑，竟是虚招一晃调虎离山，随后抬手一剑刺向$n$l，要让这恶虎剑下伏诛。正是一招「$M」。]],["id"]=[[270033]],["moveId"]=60220,["seriesId"]=27},["270034"]={["action"]=[[$N手腕一震，抖出剑花平地空中各刺一剑，剑势刚直硬猛，剑招乱花迷眼，似是猛虎嬉戏。正是一招「$M」。]],["id"]=[[270034]],["moveId"]=60220,["seriesId"]=27},["270035"]={["action"]=[[$N神色一肃，动作身形突然好似出猎的老虎，挥剑斜斜劈向$n的$l，随后手腕一拧又是一刺。正是一招「$M」。]],["id"]=[[270035]],["moveId"]=60230,["seriesId"]=27},["270036"]={["action"]=[[只听$N一声大喝，挥剑疾斩，剑刃如虎策群羊，斩向$n的$l，谁知$N暗藏后手，一剑斩完又是一刺，正是一招「$M」。]],["id"]=[[270036]],["moveId"]=60240,["seriesId"]=27},["270037"]={["action"]=[[$N使出一式「$M」，闲庭信步举剑一劈一刺，只见剑光掠闪，剑芒仿佛在半空化成虎口獠牙，欲将$n的$l撕成碎片。]],["id"]=[[270037]],["moveId"]=60250,["seriesId"]=27},["270038"]={["action"]=[[$N使一招「$M」手中$w直射$n的$l，趁$n措手不及之际$N抬手一揽又将$w握入手中，复出一剑，似猛虎扑猎连连。]],["id"]=[[270038]],["moveId"]=60260,["seriesId"]=27},["270039"]={["action"]=[[只见$w一招「$M」顿时飞剑沙石倒卷而来，紧接着$N虎扑向前，一刺好似黑虎穿心，直穿$n的$l，令人叹为观止。]],["id"]=[[270039]],["moveId"]=60270,["seriesId"]=27},["27004"]={["action"]=[[只见$N一记「$M」，掣剑一跃，在空中扭转身形，头下脚上如恶虎压顶一般挥剑刺向$n的$l。]],["id"]=[[27004]],["moveId"]=60040,["seriesId"]=27},["270040"]={["action"]=[[一把$w被$N掷出，随后$N身如插翅之虎紧随其后，霎那间抬手接剑复出一剑，若猛虎出山攻向$n的$l。正是一招「$M」。]],["id"]=[[270040]],["moveId"]=60280,["seriesId"]=27},["270041"]={["action"]=[[$N暗送巧劲，将$w掷到$n的$l，$w如饿虎穿林，猎出而复返，$N随手接复又劈出，令$n应接不暇。正是一招「$M」。]],["id"]=[[270041]],["moveId"]=60290,["seriesId"]=27},["270042"]={["action"]=[[$N前踏数步，虎步盘行，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，随后收剑虎踞，傲对千夫。]],["id"]=[[270042]],["moveId"]=60300,["seriesId"]=27},["270043"]={["action"]=[[$N前踏数步，虎步盘行，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，随后收剑虎踞，傲对千夫。]],["id"]=[[270043]],["moveId"]=60310,["seriesId"]=27},["270044"]={["action"]=[[此一招「$M」，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，直取$n的$l，身姿有若猛虎上下腾挪。]],["id"]=[[270044]],["moveId"]=60320,["seriesId"]=27},["270045"]={["action"]=[[此一招「$M」，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，直取$n的$l，身姿有若猛虎上下腾挪。]],["id"]=[[270045]],["moveId"]=60330,["seriesId"]=27},["270046"]={["action"]=[[$N振臂一扬，好似地上猛虎飞扑鸿雁，身子冲天而起，一招「$M」半空中挥剑连连，直斩$n的$l。]],["id"]=[[270046]],["moveId"]=60340,["seriesId"]=27},["270047"]={["action"]=[[$N振臂一扬，好似地上猛虎飞扑鸿雁，身子冲天而起，一招「$M」半空中挥剑连连，直斩$n的$l。]],["id"]=[[270047]],["moveId"]=60350,["seriesId"]=27},["270048"]={["action"]=[[$N岿然不动，静待时机。须臾间$N一剑横斩，剑势似有所阻，$N虎吼一声复出一剑，当真虎啸山河。正是一招「$M」。]],["id"]=[[270048]],["moveId"]=60360,["seriesId"]=27},["270049"]={["action"]=[[$N如疯虎夺食，只见$N手腕一抖，手中$w来回斩向$n的$l，剑未及身却让$n大感切肤之痛。正是一招「$M」。]],["id"]=[[270049]],["moveId"]=60370,["seriesId"]=27},["27005"]={["action"]=[[$N身形似虎跃山涧，跃上半空，而后手腕一抖$w剑刃挽起，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[27005]],["moveId"]=60050,["seriesId"]=27},["270050"]={["action"]=[[$N突出一剑，剑如虎牙先啮$n心口，而后身形流转，持剑冲天倒挂，剑锋直指$n的$l。正是一招「$M」。]],["id"]=[[270050]],["moveId"]=60380,["seriesId"]=27},["270051"]={["action"]=[[$w剑尖直颤，击向$n的$l，不料却是虚招一晃调虎离山，$N落上$n头顶破绽，提剑再刺，方要打虎入牢。正是一招「$M」。]],["id"]=[[270051]],["moveId"]=60390,["seriesId"]=27},["270052"]={["action"]=[[$N出剑若猛虎，剑尖一送却是点在$n心口，突然剑招一改，如老虎先扑再咬，$w凌空一剑刺向$n的$l。正是一招「$M」。]],["id"]=[[270052]],["moveId"]=60400,["seriesId"]=27},["270053"]={["action"]=[[$N如虎猎食，牢牢锁定$n气机，手中$w突然而发，一招「$M」使来令人眼花缭乱，剑势凌厉直取$n的$l。]],["id"]=[[270053]],["moveId"]=60410,["seriesId"]=27},["270054"]={["action"]=[[$N剑尖指地疾走数步，片刻来到$n身前狂攻$n的$l，手中$w挥得像一个恶虎磨牙吮血，似要择人而噬。正是一招「$M」。]],["id"]=[[270054]],["moveId"]=60420,["seriesId"]=27},["270055"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记虎跃跳斩劈向$n的$l，当真是恶虎扑羊，势不可挡。正是一招「$M」。]],["id"]=[[270055]],["moveId"]=60430,["seriesId"]=27},["270056"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记虎跃跳斩劈向$n的$l，当真是恶虎扑羊，势不可挡。正是一招「$M」。]],["id"]=[[270056]],["moveId"]=60440,["seriesId"]=27},["270057"]={["action"]=[[$N运剑迅猛如虎，手持$w朝着$n的$l狠狠劈来，突然一劈自上而下更如白虎凌空一纵，让$n难以招架。正是一招「$M」。]],["id"]=[[270057]],["moveId"]=60450,["seriesId"]=27},["270058"]={["action"]=[[只见$N一记「$M」身形直转，手中$w左右斩向$n的$l，却是为最后一下兜头跳斩做下铺垫，真如猛虎跳下山林。]],["id"]=[[270058]],["moveId"]=60460,["seriesId"]=27},["270059"]={["action"]=[[只见$N丝毫不歇，剑势如二虎相争，攻向$n的$l，左扫一剑，右斩一击，最后又是一记下劈斩。正是一招「$M」。]],["id"]=[[270059]],["moveId"]=60470,["seriesId"]=27},["27006"]={["action"]=[[$N身形似虎跃山涧，跃上半空，而后手腕一抖$w剑刃挽起，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[27006]],["moveId"]=60060,["seriesId"]=27},["270060"]={["action"]=[[$N静如老虎盘踞，动如猛虎出闸，指间剑柄一旋，霎那间已经凌空劈出三剑，剑剑欲将$n$l洞穿。正是一招「$M」。]],["id"]=[[270060]],["moveId"]=60480,["seriesId"]=27},["270061"]={["action"]=[[$N持剑虎形迎上，直直逼到$n身前，抬手直刺横斩接下劈，攻向$n的$l，动作一气呵成，势如恶虎吞羊。正是一招「$M」。]],["id"]=[[270061]],["moveId"]=60490,["seriesId"]=27},["270062"]={["action"]=[[$N握剑而攻，剑招仿佛老虎先咬后抓，在$n的$l先刺后扬，顿时大开大阖剑劈纵横，让$n倒吸一口凉气。正是一招「$M」。]],["id"]=[[270062]],["moveId"]=60500,["seriesId"]=27},["270063"]={["action"]=[[猛然间$N身影闪烁不定，好似虎添双翼，飞天遁地无处不在，一剑刺向$n的$l，角度刁钻让$n无法可想。正是一招「$M」。]],["id"]=[[270063]],["moveId"]=60510,["seriesId"]=27},["27007"]={["action"]=[[$N进退之间突然神色一凛，手中$w携虎吞山河之势横劈$n的$l，其剑势让$n自觉难以招架。正是一招「$M」。]],["id"]=[[27007]],["moveId"]=60070,["seriesId"]=27},["27008"]={["action"]=[[$N飞身跃起，祭出一式「$M」，$w震颤不绝发出一声虎啸之音，从半空中灌向$n的$l，真是势不可挡。]],["id"]=[[27008]],["moveId"]=60080,["seriesId"]=27},["27009"]={["action"]=[[$N一式「$M」，身形往前一探，只见白光一闪，利刃恶虎扑羊般斩向$n的$l。]],["id"]=[[27009]],["moveId"]=60090,["seriesId"]=27},["28001"]={["action"]=[[只见$N使出一记「$M」，手中$w化成一朵剑花，直奔$n的$l而去，可谓心剑合一，心花怒放。]],["id"]=[[28001]],["moveId"]=60010,["seriesId"]=28},["280010"]={["action"]=[[$N一式「$M」，身形往前一探，只见白光一闪，利刃如一道划破夜空的急雷，直取$n的$l。]],["id"]=[[280010]],["moveId"]=60100,["seriesId"]=28},["280011"]={["action"]=[[$N手握$w须臾一斩，横空洒下一段剑光匹练，宛若桃花折枝落英缤纷，直击$n的$l。正是一招「$M」。]],["id"]=[[280011]],["moveId"]=60110,["seriesId"]=28},["280012"]={["action"]=[[$N双腿一曲，身形弹射而起，持剑在地面掠尽残花败叶，身形似拂柳分花，手中$w直直劈向$n的$l。正是一招「$M」。]],["id"]=[[280012]],["moveId"]=60120,["seriesId"]=28},["280013"]={["action"]=[[$N双腿一曲，身形弹射而起，持剑在地面掠尽残花败叶，身形似拂柳分花，手中$w直直劈向$n的$l。正是一招「$M」。]],["id"]=[[280013]],["moveId"]=60130,["seriesId"]=28},["280014"]={["action"]=[[只见$N使出一式「$M」，手腕一震，$w顷刻投出。$w似要摧兰折玉弄落花，携带破空之声飞向$n的$l。]],["id"]=[[280014]],["moveId"]=60140,["seriesId"]=28},["280015"]={["action"]=[[$N斜倚长剑，长啸而歌，挥剑如孤芳自赏，柳暗花明间$w自肋下翻刺而出，刺向$n的$l。正是一招「$M」。]],["id"]=[[280015]],["moveId"]=60150,["seriesId"]=28},["280016"]={["action"]=[[$N斜倚长剑，长啸而歌，挥剑如孤芳自赏，柳暗花明间$w自肋下翻刺而出，刺向$n的$l。正是一招「$M」。]],["id"]=[[280016]],["moveId"]=60160,["seriesId"]=28},["280017"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，直取$n的$l，竟似春花抽芽。]],["id"]=[[280017]],["moveId"]=60170,["seriesId"]=28},["280018"]={["action"]=[[$N身形拔地而起，手中$w舞动，满天剑气化作阵阵花雨，一招「$M」罩向$n的$l。]],["id"]=[[280018]],["moveId"]=60170,["seriesId"]=28},["280019"]={["action"]=[[$N洒然一笑，剑招散乱，身形忽起忽落。使出「$M」手中$w水月镜花般地向$n的$l连攻数剑。]],["id"]=[[280019]],["moveId"]=60170,["seriesId"]=28},["28002"]={["action"]=[[$N使一招「$M」，突然身形暴涨，快若飞花，手中$w一摆似是一朵玫瑰带刺，向$n的$l直刺而去。]],["id"]=[[28002]],["moveId"]=60020,["seriesId"]=28},["280020"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，直取$n的$l，竟似春花抽芽。]],["id"]=[[280020]],["moveId"]=60180,["seriesId"]=28},["280021"]={["action"]=[[$N身形拔地而起，手中$w舞动，满天剑气化作阵阵花雨，一招「$M」罩向$n的$l。]],["id"]=[[280021]],["moveId"]=60180,["seriesId"]=28},["280022"]={["action"]=[[$N洒然一笑，剑招散乱，身形忽起忽落。使出「$M」手中$w水月镜花般地向$n的$l连攻数剑。]],["id"]=[[280022]],["moveId"]=60180,["seriesId"]=28},["280023"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，直取$n的$l，竟似春花抽芽。]],["id"]=[[280023]],["moveId"]=60190,["seriesId"]=28},["280024"]={["action"]=[[$N身形拔地而起，手中$w舞动，满天剑气化作阵阵花雨，一招「$M」罩向$n的$l。]],["id"]=[[280024]],["moveId"]=60190,["seriesId"]=28},["280025"]={["action"]=[[$N洒然一笑，剑招散乱，身形忽起忽落。使出「$M」手中$w水月镜花般地向$n的$l连攻数剑。]],["id"]=[[280025]],["moveId"]=60190,["seriesId"]=28},["280026"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，直取$n的$l，竟似春花抽芽。]],["id"]=[[280026]],["moveId"]=60200,["seriesId"]=28},["280027"]={["action"]=[[$N身形拔地而起，手中$w舞动，满天剑气化作阵阵花雨，一招「$M」罩向$n的$l。]],["id"]=[[280027]],["moveId"]=60200,["seriesId"]=28},["280028"]={["action"]=[[$N洒然一笑，剑招散乱，身形忽起忽落。使出「$M」手中$w水月镜花般地向$n的$l连攻数剑。]],["id"]=[[280028]],["moveId"]=60200,["seriesId"]=28},["280029"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，直取$n的$l，竟似春花抽芽。]],["id"]=[[280029]],["moveId"]=60210,["seriesId"]=28},["28003"]={["action"]=[[$N右手擎剑，衣襟头发随风而动，须臾间仿佛昙花一现，$N出剑直刺$n的$l，让人猝不及防。正是一招「$M」。]],["id"]=[[28003]],["moveId"]=60030,["seriesId"]=28},["280030"]={["action"]=[[$N身形拔地而起，手中$w舞动，满天剑气化作阵阵花雨，一招「$M」罩向$n的$l。]],["id"]=[[280030]],["moveId"]=60210,["seriesId"]=28},["280031"]={["action"]=[[$N洒然一笑，剑招散乱，身形忽起忽落。使出「$M」手中$w水月镜花般地向$n的$l连攻数剑。]],["id"]=[[280031]],["moveId"]=60210,["seriesId"]=28},["280032"]={["action"]=[[此一招「$M」腾空一击，只见$N连连改换身形，眨眼间运起$w平刺一剑，直取$n的$l，竟似春花抽芽。]],["id"]=[[280032]],["moveId"]=60220,["seriesId"]=28},["280033"]={["action"]=[[$N身形拔地而起，手中$w舞动，满天剑气化作阵阵花雨，一招「$M」罩向$n的$l。]],["id"]=[[280033]],["moveId"]=60220,["seriesId"]=28},["280034"]={["action"]=[[$N洒然一笑，剑招散乱，身形忽起忽落。使出「$M」手中$w水月镜花般地向$n的$l连攻数剑。]],["id"]=[[280034]],["moveId"]=60220,["seriesId"]=28},["280035"]={["action"]=[[$N微微一笑，动作身形好似问柳寻花，挥剑斜斜劈向$n的$l，随后手腕一拧又是一刺。正是一招「$M」。]],["id"]=[[280035]],["moveId"]=60230,["seriesId"]=28},["280036"]={["action"]=[[$N暴喝一声，身子拔高数尺，$w递出，一招「$M」伏倒一片花丛，罩住$n的$l，$n只觉身被花刺环绕。]],["id"]=[[280036]],["moveId"]=60240,["seriesId"]=28},["280037"]={["action"]=[[$N使出一式「$M」，闲庭信步举剑一劈一刺，只见剑光掠闪，剑花层层叠叠，花团锦簇，直击$n的$l。]],["id"]=[[280037]],["moveId"]=60250,["seriesId"]=28},["280038"]={["action"]=[[$N手腕一抖，手中$w飞掠而出，趁$n措手不及之际，$N又复出一剑击向$n的$l，真似山野处处开花。正是一招「$M」。]],["id"]=[[280038]],["moveId"]=60260,["seriesId"]=28},["280039"]={["action"]=[[只见$w飞掷而出，顿时飞剑飞花倒卷而来，紧接着$N疾步向前，一刺似花枝穿透$n的$l，令人倒吸冷气。正是一招「$M」。]],["id"]=[[280039]],["moveId"]=60270,["seriesId"]=28},["28004"]={["action"]=[[只见$N一记「$M」，掣剑一跃，在空中扭转身形，头下脚上如天女散花一般挥剑刺向$n的$l。]],["id"]=[[28004]],["moveId"]=60040,["seriesId"]=28},["280040"]={["action"]=[[眼前剑光疾驰闪过，竟是一把$w被$N掷向$n的$l，$N移花接木紧随其后复出一剑，似一团纷乱的落花。正是一招「$M」。]],["id"]=[[280040]],["moveId"]=60280,["seriesId"]=28},["280041"]={["action"]=[[$N暗送巧劲，掷$w到$n面前，$w如弄花蜂蝶，掠而复返，$N随手接复又劈向$n的$l，令$n眼花缭乱。正是一招「$M」。]],["id"]=[[280041]],["moveId"]=60290,["seriesId"]=28},["280042"]={["action"]=[[$N前踏数步，步步莲花，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，收剑而立，静待花开。正是一招「$M」。]],["id"]=[[280042]],["moveId"]=60300,["seriesId"]=28},["280043"]={["action"]=[[$N前踏数步，步步莲花，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，收剑而立，静待花开。正是一招「$M」。]],["id"]=[[280043]],["moveId"]=60310,["seriesId"]=28},["280044"]={["action"]=[[此一招「$M」，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，直攻$n的$l，身姿有若纷花飞舞。]],["id"]=[[280044]],["moveId"]=60320,["seriesId"]=28},["280045"]={["action"]=[[此一招「$M」，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，直攻$n的$l，身姿有若纷花飞舞。]],["id"]=[[280045]],["moveId"]=60330,["seriesId"]=28},["280046"]={["action"]=[[$N振臂一扬，似花瓣飘零半空，身子冲天而起，一招「$M」半空中挥剑连连，直斩$n的$l，剑花乱花迷眼让人胆战心惊。]],["id"]=[[280046]],["moveId"]=60340,["seriesId"]=28},["280047"]={["action"]=[[$N振臂一扬，似花瓣飘零半空，身子冲天而起，一招「$M」半空中挥剑连连，直斩$n的$l，剑花乱花迷眼让人胆战心惊。]],["id"]=[[280047]],["moveId"]=60350,["seriesId"]=28},["280048"]={["action"]=[[只听$N洒然一笑，挥剑如刀，行进间剑如花开盛放，来回横扫，身前残花枯叶皆被一扫而空。正是一招「$M」。]],["id"]=[[280048]],["moveId"]=60360,["seriesId"]=28},["280049"]={["action"]=[[$N好似一团飞花，没入$n攻势之中，只见$N手腕一抖，手中$w来回两斩攻向$n的$l，让$n只觉花香四溢。正是一招「$M」。]],["id"]=[[280049]],["moveId"]=60370,["seriesId"]=28},["28005"]={["action"]=[[$N身形似一只花间蝴蝶，跃上半空，而后手腕一抖挽起剑花，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[28005]],["moveId"]=60050,["seriesId"]=28},["280050"]={["action"]=[[$N突出一剑，剑芒吞吐不定，柳暗花明间直刺$n的$l，而后身形流转，持剑如蔷薇倒挂，剑锋直指$n的$l。正是一招「$M」。]],["id"]=[[280050]],["moveId"]=60380,["seriesId"]=28},["280051"]={["action"]=[[只见$w剑尖直颤，猛然击向$n的$l，剑出时似折柳残花，$N落上$n头顶破绽，提剑再刺，更似春花抽芽。正是一招「$M」。]],["id"]=[[280051]],["moveId"]=60390,["seriesId"]=28},["280052"]={["action"]=[[$N身如花瓣随风飘摇，一式「$M」使出，伏身下刺后翻身跃起，手中$w如拈花下指，疾刺$n的$l。]],["id"]=[[280052]],["moveId"]=60400,["seriesId"]=28},["280053"]={["action"]=[[$N只闻一声叹息，一道剑花在半空明灭不定，如花谢花开，春去秋来，凝实的剑气欲将$n的$l刺个洞穿。正是一招「$M」。]],["id"]=[[280053]],["moveId"]=60410,["seriesId"]=28},["280054"]={["action"]=[[$N剑尖指地疾走数步，疾攻$n的$l，只见$N振臂频挥，手中$w剑花连连，所到之处残花折柳，玉碎花销。正是一招「$M」。]],["id"]=[[280054]],["moveId"]=60420,["seriesId"]=28},["280055"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记飞花跳斩，直劈$n的$l，似是春花怒放，万紫千红。正是一招「$M」。]],["id"]=[[280055]],["moveId"]=60430,["seriesId"]=28},["280056"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记飞花跳斩，直劈$n的$l，似是春花怒放，万紫千红。正是一招「$M」。]],["id"]=[[280056]],["moveId"]=60440,["seriesId"]=28},["280057"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记飞花跳斩，直劈$n的$l，似是春花怒放，万紫千红。正是一招「$M」。]],["id"]=[[280057]],["moveId"]=60450,["seriesId"]=28},["280058"]={["action"]=[[只见$N一记「$M」身形直转，手中$w左右横斩，最后一记兜头跳斩，剑光更似火树银花，直劈$n的$l。]],["id"]=[[280058]],["moveId"]=60460,["seriesId"]=28},["280059"]={["action"]=[[只见$N丝毫不歇，剑势如梨花带雨，攻向$n的$l，剑影上下左右各自袭来。正是一招「$M」。]],["id"]=[[280059]],["moveId"]=60470,["seriesId"]=28},["28006"]={["action"]=[[$N身形似一只花间蝴蝶，跃上半空，而后手腕一抖挽起剑花，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[28006]],["moveId"]=60060,["seriesId"]=28},["280060"]={["action"]=[[只见$N身影动若飞花夺叶，于平地、半空劈出数剑，连斩$n的$l，剑上杀意让人寒毛直立。]],["id"]=[[280060]],["moveId"]=60480,["seriesId"]=28},["280061"]={["action"]=[[$N持剑来攻，脚下步步莲花，直直逼到$n身前，抬手直刺横斩接下劈，攻向$n的$l，势如百花齐放。正是一招「$M」。]],["id"]=[[280061]],["moveId"]=60490,["seriesId"]=28},["280062"]={["action"]=[[$N握剑而攻，剑招仿佛春雪消融百花盛放，$w在$n的$l上一蛰即改，顿时大开大阖剑劈纵横，正是一招「$M」。]],["id"]=[[280062]],["moveId"]=60500,["seriesId"]=28},["280063"]={["action"]=[[猛然间$N身影闪烁不定，好似零落纷花，飞天遁地无处不在，手中$w时不时攻向$n的$l，正是一招「$M」。]],["id"]=[[280063]],["moveId"]=60510,["seriesId"]=28},["28007"]={["action"]=[[$N进退之间突然神色一凛，手中$w绽放出朵朵剑花，其剑势让$n只觉眼花缭乱。正是一招「$M」。]],["id"]=[[28007]],["moveId"]=60070,["seriesId"]=28},["28008"]={["action"]=[[$N使出一招「$M」，猛然间腾空而起，悬于半空，手中$w掠过地面扫尽残花败叶，直击$n的$l。]],["id"]=[[28008]],["moveId"]=60080,["seriesId"]=28},["28009"]={["action"]=[[$N一式「$M」，身形往前一探，只见白光一闪，利刃如一道划破夜空的急雷，直取$n的$l。]],["id"]=[[28009]],["moveId"]=60090,["seriesId"]=28},["29001"]={["action"]=[[只见$N使出一记「$M」，一剑化作一川江水，向$n的$l刺去，似是江心一点，大江东去。]],["id"]=[[29001]],["moveId"]=60010,["seriesId"]=29},["290010"]={["action"]=[[$N一式「$M」，身形往前一探，$w划出一道白痕，仿佛江天合于一线，随后浊浪排空，直取$n的$l。]],["id"]=[[290010]],["moveId"]=60100,["seriesId"]=29},["290011"]={["action"]=[[$N手握$w须臾一斩，一式「$M」横空洒下一段剑光匹练，宛若恒河之沙，星星点点洒落，直击$n的$l。]],["id"]=[[290011]],["moveId"]=60110,["seriesId"]=29},["290012"]={["action"]=[[$N双腿一曲，身形弹射而起，持剑似在江面飞掠流转，一式「$M」利刃似