39"]={["action"]=[[$w飞掷而出，顿时飞剑如电倒卷而来，紧接着$N疾步向前，一刺好似惊雷穿透$n的$l，令人倒吸冷气。正是一招「$M」。]],["id"]=[[300039]],["moveId"]=60270,["seriesId"]=30},["30004"]={["action"]=[[只见$N一记「$M」，掣剑一跃，在空中扭转身形，头下脚上如天雷灌脑一般挥剑刺向$n的$l。]],["id"]=[[30004]],["moveId"]=60040,["seriesId"]=30},["300040"]={["action"]=[[一把$w被$N掷向$n的$l，随后$N身如迅雷紧随其后，霎那间抬手接剑复出一剑，似一道晃眼的急雷。正是一招「$M」。]],["id"]=[[300040]],["moveId"]=60280,["seriesId"]=30},["300041"]={["action"]=[[$N暗送巧劲，掷$w到$n面前，$w如长剑引雷，掠而复返，$N随手接复又劈向$n的$l，令$n应接不暇。正是一招「$M」。]],["id"]=[[300041]],["moveId"]=60290,["seriesId"]=30},["300042"]={["action"]=[[$N前踏数步，惊雷激荡，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，收剑而立，傲对苍雷。正是一招「$M」。]],["id"]=[[300042]],["moveId"]=60300,["seriesId"]=30},["300043"]={["action"]=[[$N前踏数步，惊雷激荡，蓦然间连出两剑，剑影上下翻飞，直指$n的$l，收剑而立，傲对苍雷。正是一招「$M」。]],["id"]=[[300043]],["moveId"]=60310,["seriesId"]=30},["300044"]={["action"]=[[此一招「$M」，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，直攻$n的$l，身姿有若破空惊雷。]],["id"]=[[300044]],["moveId"]=60320,["seriesId"]=30},["300045"]={["action"]=[[此一招「$M」，只见$N连连改换身形，眨眼间挥动$w斜向上劈接腾起下劈，直攻$n的$l，身姿有若破空惊雷。]],["id"]=[[300045]],["moveId"]=60330,["seriesId"]=30},["300046"]={["action"]=[[$N振臂一扬，好似平地激起飞雷，身子冲天而起，一招「$M」半空中挥剑连连直斩$n的$l，剑光电流霆击让人胆战心惊。]],["id"]=[[300046]],["moveId"]=60340,["seriesId"]=30},["300047"]={["action"]=[[$N振臂一扬，好似平地激起飞雷，身子冲天而起，一招「$M」半空中挥剑连连直斩$n的$l，剑光电流霆击让人胆战心惊。]],["id"]=[[300047]],["moveId"]=60350,["seriesId"]=30},["300048"]={["action"]=[[$N岿然不动，静待时机。须臾间$N一剑横斩先声夺人，$N复出一剑又斩$n的$l，如电光先闪随后响雷。正是一招「$M」。]],["id"]=[[300048]],["moveId"]=60360,["seriesId"]=30},["300049"]={["action"]=[[$N似一团急雷，手腕一抖，手中$w来回两斩攻向$n的$l，似是一团电流让$n汗毛倒竖。正是一招「$M」。]],["id"]=[[300049]],["moveId"]=60370,["seriesId"]=30},["30005"]={["action"]=[[$N身形似一团奔腾的雷云，跃上半空，而后手腕一抖剑颤雷鸣，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[30005]],["moveId"]=60050,["seriesId"]=30},["300050"]={["action"]=[[$N突出一剑，剑如紫电青雷直刺$n的$l，而后身形流转，持剑冲天倒挂，剑锋直指$n的$l。正是一招「$M」。]],["id"]=[[300050]],["moveId"]=60380,["seriesId"]=30},["300051"]={["action"]=[[只见$w剑尖直颤，猛然击向$n的$l，剑出时似破空炸雷，$N落上$n头顶破绽，提剑再刺，更似晴天霹雳。正是一招「$M」。]],["id"]=[[300051]],["moveId"]=60390,["seriesId"]=30},["300052"]={["action"]=[[$N出剑若疾雷，剑尖一送却是点在$n$l，突然剑招一改，剑吟雷鸣合二为一，$w凌空一剑破空刺来。正是一招「$M」。]],["id"]=[[300052]],["moveId"]=60400,["seriesId"]=30},["300053"]={["action"]=[[$N只闻一声叹息，一道剑光在半空闪烁三次，悄如长夜，灿若闪雷，凝实的剑气欲将$n的$l刺个洞穿。正是一招「$M」。]],["id"]=[[300053]],["moveId"]=60410,["seriesId"]=30},["300054"]={["action"]=[[$N剑尖指地疾奔如雷，来到$n身前，只见$N振臂频挥，手中$w挥得白光连连，似电芒急转，攻向$n的$l。正是一招「$M」。]],["id"]=[[300054]],["moveId"]=60420,["seriesId"]=30},["300055"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记天雷跳斩，直劈$n的$l，当真是云暗雷灿，势不可挡。正是一招「$M」。]],["id"]=[[300055]],["moveId"]=60430,["seriesId"]=30},["300056"]={["action"]=[[只见$N手握$w劈来劈去，须臾间又是一记天雷跳斩，直劈$n的$l，当真是云暗雷灿，势不可挡。正是一招「$M」。]],["id"]=[[300056]],["moveId"]=60440,["seriesId"]=30},["300057"]={["action"]=[[$N运剑迅猛如雷，挥动$w如雷雨交加，身形上下翻飞，阵阵劈向$n的$l，让$n难以招架。正是一招「$M」。]],["id"]=[[300057]],["moveId"]=60450,["seriesId"]=30},["300058"]={["action"]=[[只见$N一记「$M」身形直转，手中$w左右横斩，最后一记兜头跳斩更似雨后狂雷，直劈$n的$l。]],["id"]=[[300058]],["moveId"]=60460,["seriesId"]=30},["300059"]={["action"]=[[只见$N丝毫不歇，剑势如烈雨狂雷，攻向$n的$l，左扫一剑，右斩一击，最后又是一记下劈斩。正是一招「$M」。]],["id"]=[[300059]],["moveId"]=60470,["seriesId"]=30},["30006"]={["action"]=[[$N身形似一团奔腾的雷云，跃上半空，而后手腕一抖剑颤雷鸣，剑尖向下刺向$n的$l。正是一招「$M」。]],["id"]=[[30006]],["moveId"]=60060,["seriesId"]=30},["300060"]={["action"]=[[只听一声雷鸣呼啸，$N身影动若奔雷，于平地、半空劈出数剑，连斩$n的$l，剑上杀意让人寒毛直立。正是一招「$M」。]],["id"]=[[300060]],["moveId"]=60480,["seriesId"]=30},["300061"]={["action"]=[[$N持剑步若奔雷，直直逼到$n身前，抬手直刺横斩接下劈，攻向$n的$l，动作一气呵成，势如怒电轰雷。正是一招「$M」。]],["id"]=[[300061]],["moveId"]=60490,["seriesId"]=30},["300062"]={["action"]=[[$N握剑而攻，一记「$M」剑招如晴空万里骤起惊雷，$w在$n的$l上一蛰即改，顿时大开大阖剑劈纵横，让$n倒吸凉气。]],["id"]=[[300062]],["moveId"]=60500,["seriesId"]=30},["300063"]={["action"]=[[猛然间$N身影闪烁不定，好似一道电光，手中$w时不时攻向$n的$l，剑若奔雷让$n难以抵挡。正是一招「$M」。]],["id"]=[[300063]],["moveId"]=60510,["seriesId"]=30},["30007"]={["action"]=[[$N进退之间突然神色一凛，手中$w携雷霆万钧之势横劈$n的$l，其剑势让$n自觉难以招架。正是一招「$M」。]],["id"]=[[30007]],["moveId"]=60070,["seriesId"]=30},["30008"]={["action"]=[[$N飞身跃起，祭出一式「$M」，$w震颤不绝发出一声雷鸣之音，从半空中劈向$n的$l，真是势不可挡。]],["id"]=[[30008]],["moveId"]=60080,["seriesId"]=30},["30009"]={["action"]=[[$N一式「$M」，身形往前一探，只见白光一闪，利刃如一道划破夜空的急雷，直取$n的$l。]],["id"]=[[30009]],["moveId"]=60090,["seriesId"]=30},["3001"]={["action"]=[[$N一招「$M」，站在原地巍然不动，双掌朝前拍出满天狂风，不断扫向$n的$l。]],["id"]=[[3001]],["moveId"]=20010,["seriesId"]=3},["30010"]={["action"]=[[$N将真气凝聚于双掌掌心，一招「$M」，踏步向前，信手击出，连续两击都带着呼呼呼的气流声，对准$n的$l拍去。]],["id"]=[[30010]],["moveId"]=20040,["seriesId"]=3},["30011"]={["action"]=[[$N一招「$M」，站在原地巍然不动，双掌朝前拍出满天狂风，不断扫向$n的$l。]],["id"]=[[30011]],["moveId"]=20050,["seriesId"]=3},["30012"]={["action"]=[[$N双手齐划，跟着双掌齐推，一招「$M」，一股铺天盖地、飞沙走石的掌风，直扑$n$l。]],["id"]=[[30012]],["moveId"]=20050,["seriesId"]=3},["30013"]={["action"]=[[$N将真气凝聚于双掌掌心，一招「$M」，踏步向前，信手击出，连续两击都带着呼呼呼的气流声，对准$n的$l拍去。]],["id"]=[[30013]],["moveId"]=20050,["seriesId"]=3},["30014"]={["action"]=[[$N一招「$M」，站在原地巍然不动，双掌朝前拍出满天狂风，不断扫向$n的$l。]],["id"]=[[30014]],["moveId"]=20060,["seriesId"]=3},["30015"]={["action"]=[[$N双手齐划，跟着双掌齐推，一招「$M」，一股铺天盖地、飞沙走石的掌风，直扑$n$l。]],["id"]=[[30015]],["moveId"]=20060,["seriesId"]=3},["30016"]={["action"]=[[$N将真气凝聚于双掌掌心，一招「$M」，踏步向前，信手击出，连续两击都带着呼呼呼的气流声，对准$n的$l拍去。]],["id"]=[[30016]],["moveId"]=20060,["seriesId"]=3},["30017"]={["action"]=[[$N急出一招「$M」，跳身而起，双掌前推，只见尘沙飞扬，耳边狂风怒吼，威力精纯地拍向$n的$l。]],["id"]=[[30017]],["moveId"]=20070,["seriesId"]=3},["30018"]={["action"]=[[$N急出一招「$M」，跳身而起，双掌前推，只见尘沙飞扬，耳边狂风怒吼，威力精纯地拍向$n的$l。]],["id"]=[[30018]],["moveId"]=20080,["seriesId"]=3},["30019"]={["action"]=[[$N使一式「$M」，一个跟头翻身空中，双掌朝下劈出数道劲风，绵绵不断地击向$n的$l。]],["id"]=[[30019]],["moveId"]=20090,["seriesId"]=3},["3002"]={["action"]=[[$N双手齐划，跟着双掌齐推，一招「$M」，一股铺天盖地、飞沙走石的掌风，直扑$n$l。]],["id"]=[[3002]],["moveId"]=20010,["seriesId"]=3},["30020"]={["action"]=[[$N使一式「$M」，一个跟头翻身空中，双掌朝下劈出数道劲风，绵绵不断地击向$n的$l。]],["id"]=[[30020]],["moveId"]=20100,["seriesId"]=3},["30021"]={["action"]=[[$N使出一式「$M」，跃身空中，将五脏六腑的精力汇聚右掌，朝下劈出数道风刃，猛烈地攻向$n的$l。]],["id"]=[[30021]],["moveId"]=20110,["seriesId"]=3},["30022"]={["action"]=[[$N急出一招「$M」，单掌掌风阴寒，犹带寒霜地劈向$n的$l。]],["id"]=[[30022]],["moveId"]=20120,["seriesId"]=3},["30023"]={["action"]=[