esId"]=3},["30097"]={["action"]=[[$N长啸一声，使出一招「$M」，身体看起来极为轻盈，一个跟头跃至敌前，双掌三连推出，掀起一阵狂风，朝$n的$l拍去。]],["id"]=[[30097]],["moveId"]=20500,["seriesId"]=3},["30098"]={["action"]=[[$N展身虚步，提腰翻身跃落，一招「$M」双掌推出，掌风浩荡，向着$n的$l三连猛击。]],["id"]=[[30098]],["moveId"]=20500,["seriesId"]=3},["30099"]={["action"]=[[$N使出一招「$M」，空中跟头连翻，刮起黑风，双掌掌下好似涂有剧毒，三连朝$n的$l钉入。]],["id"]=[[30099]],["moveId"]=20510,["seriesId"]=3},["30100"]={["action"]=[[$N长啸一声，使出一招「$M」，身体看起来极为轻盈，一个跟头跃至敌前，双掌三连推出，掀起一阵狂风，朝$n的$l拍去。]],["id"]=30100,["moveId"]=20510,["seriesId"]=3},["30101"]={["action"]=[[$N展身虚步，提腰翻身跃落，一招「$M」双掌推出，掌风浩荡，向着$n的$l三连猛击。]],["id"]=30101,["moveId"]=20510,["seriesId"]=3},["31001"]={["action"]=[[$N大踏步向前，单手擎刀出刀横斩，刀锋凌厉，疾若狂风，始终不离$n双目。正是一招「$M」。]],["id"]=[[31001]],["moveId"]=70010,["seriesId"]=31},["310010"]={["action"]=[[$N大踏步向前，单手擎刀出刀横斩，刀锋凌厉，疾若狂风，始终不离$n双目。正是一招「$M」。]],["id"]=[[310010]],["moveId"]=70070,["seriesId"]=31},["310011"]={["action"]=[[$N单手出刀横斩，刀出如风，始终不离$n的$l。正是一招「$M」。]],["id"]=[[310011]],["moveId"]=70070,["seriesId"]=31},["310012"]={["action"]=[[$N大踏步向前，只见刀影重重，若疾风猛卷，袭向$n的$l。正是一招「$M」。]],["id"]=[[310012]],["moveId"]=70070,["seriesId"]=31},["310013"]={["action"]=[[只听$N大笑一声，使出一招「$M」，身形旋腾而起，半空中刀势大开大阖，若狂风大作，直直劈向$n的$l。]],["id"]=[[310013]],["moveId"]=70080,["seriesId"]=31},["310014"]={["action"]=[[$N跃至半空，使出一招「$M」，双手握住$w，一招下斩攻向$n的$l，招式朴实无华，却快若疾风。]],["id"]=[[310014]],["moveId"]=70090,["seriesId"]=31},["310015"]={["action"]=[[$N身形上纵，使出一招「$M」，双手握住$w，一刀斩出，宛若疾风骤临，攻向$n的$l。]],["id"]=[[310015]],["moveId"]=70100,["seriesId"]=31},["310016"]={["action"]=[[$N扭身曲臂，跃于空中。蓦然间时机已至，只见$N振臂一挥，使出一招「$M」，手中$w势如狂风，直奔向$n的$l。]],["id"]=[[310016]],["moveId"]=70110,["seriesId"]=31},["310017"]={["action"]=[[只见$N单手持提刀向前疾走，须臾间小臂一震，手中$w挟裹一股狂风直刺向$n的$l。正是一式「$M」。]],["id"]=[[310017]],["moveId"]=70120,["seriesId"]=31},["310018"]={["action"]=[[$N大踏步向前，单手擎刀出刀横斩，刀锋凌厉，疾若狂风，始终不离$n双目。正是一招「$M」。]],["id"]=[[310018]],["moveId"]=70130,["seriesId"]=31},["310019"]={["action"]=[[$N单手出刀横斩，刀出如风，始终不离$n的$l。正是一招「$M」。]],["id"]=[[310019]],["moveId"]=70130,["seriesId"]=31},["31002"]={["action"]=[[$N单手出刀横斩，刀出如风，始终不离$n的$l。正是一招「$M」。]],["id"]=[[31002]],["moveId"]=70010,["seriesId"]=31},["310020"]={["action"]=[[$N大踏步向前，只见刀影重重，若疾风猛卷，袭向$n的$l。正是一招「$M」。]],["id"]=[[310020]],["moveId"]=70130,["seriesId"]=31},["310021"]={["action"]=[[只见$N双臂高举，手中$w携狂风漫卷之势一挥而下。正是一招「$M」。]],["id"]=[[310021]],["moveId"]=70140,["seriesId"]=31},["310022"]={["action"]=[[蓦然间，$N将身姿挺拔，气势节节攀升，使出一招「$M」，手中$w如疾风刮劲草，反复横削，直斩$n$l。]],["id"]=[[310022]],["moveId"]=70150,["seriesId"]=31},["310023"]={["action"]=[[蓦然间，$N将身姿挺拔，气势节节攀升，使出一招「$M」，手中$w如疾风刮劲草，反复横削，直斩$n$l。]],["id"]=[[310023]],["moveId"]=70160,["seriesId"]=31},["310024"]={["action"]=[[$N神色一肃，动作身形突然变得迅猛，挥刀斜斜劈向$n的$l，随后手腕翻转$w再度劈出。出招迅若疾风，正是一招「$M」。]],["id"]=[[310024]],["moveId"]=70170,["seriesId"]=31},["310025"]={["action"]=[[$N使出一招「$M」，挺身上前，将手中$w挥洒而出，但见刀光漫漫，宛若疾风般卷向$n$l。]],["id"]=[[310025]],["moveId"]=70180,["seriesId"]=31},["310026"]={["action"]=[[$N使出一招「$M」，一招横切，劲力激起一阵旋风，直直涌向$n$l。]],["id"]=[[310026]],["moveId"]=70190,["seriesId"]=31},["310027"]={["action"]=[[$N使出一招「$M」，劲力浩荡而出，刀光飞闪之际，数股狂风已然罩向$n$l。]],["id"]=[[310027]],["moveId"]=70200,["seriesId"]=31},["310028"]={["action"]=[[只见$N深吸一口气，手中$w来回劈斩，一时间刀光密布，若疾风般卷向$n的$l。正是一招「$M」。]],["id"]=[[310028]],["moveId"]=70210,["seriesId"]=31},["310029"]={["action"]=[[$N使出一招「$M」，刀势上斩，身形同时纵上半空，宛若化作一团旋风卷向$n$l]],["id"]=[[310029]],["moveId"]=70220,["seriesId"]=31},["31003"]={["action"]=[[$N大踏步向前，只见刀影重重，若疾风猛卷，袭向$n的$l。正是一招「$M」。]],["id"]=[[31003]],["moveId"]=70010,["seriesId"]=31},["310030"]={["action"]=[[$N猱身而上，使出一招「$M」，片刻间直直劈出一刀，脚下足尖一顿，腾于半空，身子若旋风飞转，挥刀向$n的$l猛砍。]],["id"]=[[310030]],["moveId"]=70230,["seriesId"]=31},["310031"]={["action"]=[[$N使出一招「$M」，运足内劲低手一甩$w脱手而出，若风中飞石，直奔$n而去，须臾间只见又出一斩，横斜劈向$n的$l。]],["id"]=[[310031]],["moveId"]=70240,["seriesId"]=31},["310032"]={["action"]=[[$N使出一招「$M」，向$n右侧疾行数步，一道平斩而出，激起一股环形劲风，击向$n$l。]],["id"]=[[310032]],["moveId"]=70250,["seriesId"]=31},["310033"]={["action"]=[[$N身形暴涨，如若狂风般朝着$n疾掠而去，手腕一翻，手中$w狠狠劈向$n的$l。正是一招「$M」。]],["id"]=[[310033]],["moveId"]=70260,["seriesId"]=31},["310034"]={["action"]=[[$N大喝一声，使出一招「$M」，冲至$n身后，挺刀直探而出，随即上挑，宛若阴风般撩向$n$l。]],["id"]=[[310034]],["moveId"]=70270,["seriesId"]=31},["310035"]={["action"]=[[$N振臂一扬，身如飞凫冲天而起，一招「$M」半空中挥刀急斩向$n的$l，刀势密如狂风，极难抵挡。]],["id"]=[[310035]],["moveId"]=70280,["seriesId"]=31},["310036"]={["action"]=[[$N振臂一扬，身如飞凫冲天而起，一招「$M」半空中挥刀急斩向$n的$l，刀势密如狂风，极难抵挡。]],["id"]=[[310036]],["moveId"]=70290,["seriesId"]=31},["310037"]={["action"]=[[$N沉身不语悄然掠进，使出一招「$M」，倏然间只见白光一闪，$N已出两刀直斩向的$l，如若阴风吹拂，叫人防不胜防。]],["id"]=[[310037]],["moveId"]=70300,["seriesId"]=31},["310038"]={["action"]=[[$N沉身不语悄然掠进，使出一招「$M」，倏然间只见白光一闪，$N已出两刀直斩向的$l，如若阴风吹拂，叫人防不胜防。]],["id"]=[[310038]],["moveId"]=70310,["seriesId"]=31},["310039"]={["action"]=[[只听$N大笑一声，冲前数步，身形蓦然旋腾而起，半空中刀法大开大阖，密不透风，直直向$n的$l席卷而去。]],["id"]=[[310039]],["moveId"]=70320,["seriesId"]=31},["31004"]={["action"]=[[只见$N双臂高举，手中$w携狂风漫卷之势一挥而下。正是一招「$M」。]],["id"]=[[31004]],["moveId"]=70030,["seriesId"]=31},["310040"]={["action"]=[[只听$N大笑一声，冲前数步，身形蓦然旋腾而起，半空中刀法大开大阖，密不透风，直直向$n的$l席卷而去。]],["id"]=[[310040]],["moveId"]=70330,["seriesId"]=31},["310041"]={["action"]=[[$N身子向前一探，一招「$M」$w颤动，刀刃翻转如风，连出数刀，连环斩向$n的$l。]],["id"]=[[310041]],["moveId"]=70340,["seriesId"]=31},["310042"]={["action"]=[[$N突然刀势一滞，手中$w上下来回劈出，若狂风乱舞，接连斩向$n的$l，正是一招「$M」。]],["id"]=[[310042]],["moveId"]=70350,["seriesId"]=31},["310043"]={["action"]=[[$N使出一招「$M」，身形疾速转动，一刀接一刀连连上挑，宛若浩荡飓风般卷向$n$l。]],["id"]=[[310043]],["moveId"]=70360,["seriesId"]=31},["310044"]={["action"]=[[$N使出一招「$M」，手中$w如疾风般挥洒而出，刀势绵密无比，将$n周身困于重重刀影之内后，再一刀斩向$n的$l。]],["id"]=[[310044]],["moveId"]=70370,["seriesId"]=31},["310045"]={["action"]=[[$N身子一伏，若风中白羽，飘然来到$n身前，摇曳间唰唰唰向$n的$l连劈三刀。正是一招「$M」。]],["id"]=[[310045]],["moveId"]=70380,["seriesId"]=31},["310046"]={["action"]=[[$N手中利刃劈风，运转$w一招「$M」循环往复斩向$n的$l，刀锋凌厉，疾若狂风，]],["id"]=[[310046]],["moveId"]=70390,["seriesId"]=31},["310047"]={["action"]=[[$N单手擎刀，使出一招「$M」，凌空下斩，一如猛虎下山！霎那间$w宛如劈山大斧，朝着$n$l狠劈而去。]],["id"]=[[310047]],["moveId"]=70400,["seriesId"]=31},["310048"]={["action"]=[[$N提刀而至，使出一招「$M」，刀光在$n胸腹一闪而逝，随即挥洒$w，刀势席卷而出，直斩向$n的$l。]],["id"]=[[310048]],["moveId"]=70410,["seriesId"]=31},["310049"]={["action"]=[[$N提刀而至，使出一招「$M」，刀光在$n胸腹一闪而逝，随即挥洒$w，刀势席卷而出，直斩向$n的$l。]],["id"]=[[310049]],["moveId"]=70420,["seriesId"]=31},["31005"]={["action"]=[[$N大踏步向前，单手擎刀出刀横斩，刀锋凌厉，疾若狂风，始终不离$n双目。正是一招「$M」。]],["id"]=[[31005]],["moveId"]=70040,["seriesId"]=31},["310050"]={["action"]=[[$N使出一招「$M」，把$w一投，随后贴地飞空，手掌轻轻一扬，$w激起数道劲风，逼向$n的$l。]],["id"]=[[310050]],["moveId"]=70430,["seriesId"]=31},["310051"]={["action"]=[[$N使出一招「$M」，把$w一投，随后贴地飞空，手掌轻轻一扬，$w激起数道劲风，逼向$n的$l。]],["id"]=[[310051]],["moveId"]=70440,["seriesId"]=31},["310052"]={["action"]=[[$N忽然气机一凝，一招「$M」信手拈来，手中$w刃口急转，宛若旋风急转，劈出三团刀光斩向$n的$l。]],["id"]=[[310052]],["moveId"]=70450,["seriesId"]=31},["310053"]={["action"]=[[$N持刀快斩，出道绵密无比，若疾风席卷，一重重斩向$n$l，正是一招「$M」。]],["id"]=[[310053]],["moveId"]=70460,["seriesId"]=31},["310054"]={["action"]=[[$N身形若飞，将手中$w舞成狂风一般，直罩向$n$l。正是一招「$M」。]],["id"]=[[310054]],["moveId"]=70470,["seriesId"]=31},["310055"]={["action"]=[[$N突然刀势一滞，出招变化无穷，$w挥动之际，内劲纵横，激起浩荡狂风，向$n$l席卷而去，正是一招「$M」。]],["id"]=[[310055]],["moveId"]=70480,["seriesId"]=31},["310056"]={["action"]=[[只见$N信手一挥，使出一招「$M」，$w倒飞而出，劲风浩荡，但转瞬复返，朝$n的$l斜劈而下，声势甚为骇人。]],["id"]=[[310056]],["moveId"]=70490,["seriesId"]=31},["310057"]={["action"]=[[$N霎时间持刀不动，使出一招「$M」，横空跃起高举$w，一瞬之间连劈出数十刀，激起浩荡劲风，席卷向$n的$l。]],["id"]=[[310057]],["moveId"]=70500,["seriesId"]=31},["310058"]={["action"]=[[$N霎时间持刀不动，使出一招「$M」，横空跃起高举$w，一瞬之间连劈出数十刀，激起浩荡劲风，席卷向$n的$l。]],["id"]=[[310058]],["moveId"]=70510,["seriesId"]=31},["31006"]={["action"]=[[$N单手出刀横斩，刀出如风，始终不离$n的$l。正是一招「$M」。]],["id"]=[[31006]],["moveId"]=70040,["seriesId"]=31},["31007"]={["action"]=[[$N大踏步向前，只见刀影重重，若疾风猛卷，袭向$n的$l。正是一招「$M」。]],["id"]=[[31007]],["moveId"]=70040,["seriesId"]=31},["31008"]={["action"]=[[$N使出一式「$M」，只见$N单手擎刀，刀尖指地，须臾间手中$w往上一送，快若疾风。刀刃反劈向$n的$l。]],["id"]=[[31008]],["moveId"]=70050,["seriesId"]=31},["31009"]={["action"]=[[只见$N双臂高举，手中$w携狂风漫卷之势一挥而下。正是一招「$M」。]],["id"]=[[31009]],["moveId"]=70060,["seriesId"]=31},["32001"]={["action"]=[[霎那间$N身形暴涨，向着$n飞掠而去，只听$N一声大喝，手中$w向$n横劈而去，势若雷霆。正是一招「$M」。]