30]],["moveId"]=70230,["seriesId"]=34},["340031"]={["action"]=[[眼前刀光一闪，竟是一把$w被$N掷出，随后$N身形飞掠，霎那间抬手抄刀复出一斩，攻向$n的$l，竟有惊动山河之威。]],["id"]=[[340031]],["moveId"]=70240,["seriesId"]=34},["340032"]={["action"]=[[$N使出一招「$M」，快步走向$n身后，一刀横切而出，斩向$n$l，劲道之刚猛，似可横斩群山。]],["id"]=[[340032]],["moveId"]=70250,["seriesId"]=34},["340033"]={["action"]=[[只见$N孤身孤影孤刀，行尸走肉般移到$n身前，手中$w平平一斩，激起浩荡劲风，大有碎山破石之势，猛然攻向$n$l。]],["id"]=[[340033]],["moveId"]=70260,["seriesId"]=34},["340034"]={["action"]=[[$N使出一招「$M」，窜到$n身后，一刀上撩而出，刀势诡异，若山中迷雾般罩向$n$l。]],["id"]=[[340034]],["moveId"]=70270,["seriesId"]=34},["340035"]={["action"]=[[$N身先鱼跃而出，趁$n未有察觉之际现出$w，空中连挥两刀，砍向$n的$l，大有劈山动地之势。正是一招「$M」。]],["id"]=[[340035]],["moveId"]=70280,["seriesId"]=34},["340036"]={["action"]=[[$N身先鱼跃而出，趁$n未有察觉之际现出$w，空中连挥两刀，砍向$n的$l，大有劈山动地之势。正是一招「$M」。]],["id"]=[[340036]],["moveId"]=70290,["seriesId"]=34},["340037"]={["action"]=[[$N前踏数步，蓦然间连出两刀，刀影上下翻飞，直指$n的$l，激发数道劲力，有若山洪爆发涌向。正是一招「$M」。]],["id"]=[[340037]],["moveId"]=70300,["seriesId"]=34},["340038"]={["action"]=[[$N前踏数步，蓦然间连出两刀，刀影上下翻飞，直指$n的$l，激发数道劲力，有若山洪爆发涌向。正是一招「$M」。]],["id"]=[[340038]],["moveId"]=70310,["seriesId"]=34},["340039"]={["action"]=[[$N飞奔向前，须臾间双脚离地，斜飞而出，半空中引动$w劈向$n的$l，招法雄劲，有劈山之威！原来是一招「$M」。]],["id"]=[[340039]],["moveId"]=70320,["seriesId"]=34},["34004"]={["action"]=[[$N算准$n行径路线，一招「$M」半途截杀而出，手中$w在半空划出一道月牙，欲将$n一刀两断，招法雄劲，有劈山之威！]],["id"]=[[34004]],["moveId"]=70030,["seriesId"]=34},["340040"]={["action"]=[[$N飞奔向前，须臾间双脚离地，斜飞而出，半空中引动$w劈向$n的$l，招法雄劲，有劈山之威！原来是一招「$M」。]],["id"]=[[340040]],["moveId"]=70330,["seriesId"]=34},["340041"]={["action"]=[[$N只身来到$n身侧，使出一招「$M」，顷刻间$N早已连出三刀，挟裹刀劲斩向$n$l，招法老练，若山中迷雾，诡秘莫测！。]],["id"]=[[340041]],["moveId"]=70340,["seriesId"]=34},["340042"]={["action"]=[[只见$N冷冷一笑，行进间运刀如鞭，手腕一拧，数道刀影漫卷向$n的$l，有撼山动地之威。正是一招「$M」。]],["id"]=[[340042]],["moveId"]=70350,["seriesId"]=34},["340043"]={["action"]=[[$N使出一招「$M」，手中$w若三峰叠出般连斩三次，猛攻向$n$l。]],["id"]=[[340043]],["moveId"]=70360,["seriesId"]=34},["340044"]={["action"]=[[只见$N先是横刀一斩，倏然间纵身而起，兔起鹘落间举刀来回斩向$n$l，劲力浩荡，有若山洪爆发。正是一招「$M」。]],["id"]=[[340044]],["moveId"]=70370,["seriesId"]=34},["340045"]={["action"]=[[只见$w闪过道道白光，晃得人眼生疼，片刻间$N对$n$l劈出三刀，刀劲雄浑，有劈山之威。正是一招「$M」。]],["id"]=[[340045]],["moveId"]=70380,["seriesId"]=34},["340046"]={["action"]=[[$N腾身挪步跃于空中，使一招「$M」，只见$N凌空一晃，身形向着$n俯冲，手中$w直劈$n的$l，劲力刚猛，有裂山之威。]],["id"]=[[340046]],["moveId"]=70390,["seriesId"]=34},["340047"]={["action"]=[[霎时间$w刀鸣不止，宛若山石崩落，只见$N手握$w身形起落不定，使一招「$M」，出刀攻向$n$l，欲将$n斩于刀下。]],["id"]=[[340047]],["moveId"]=70400,["seriesId"]=34},["340048"]={["action"]=[[须臾间$N避开对方攻势，使一招「$M」，脚下游移不定来到$n侧身，手中$w反复斩向其$l，招法刚猛，有劈山动地之势。]],["id"]=[[340048]],["moveId"]=70410,["seriesId"]=34},["340049"]={["action"]=[[须臾间$N避开对方攻势，使一招「$M」，脚下游移不定来到$n侧身，手中$w反复斩向其$l，招法刚猛，有劈山动地之势。]],["id"]=[[340049]],["moveId"]=70420,["seriesId"]=34},["34005"]={["action"]=[[只见$N使出一招「$M」，平伸单刀，恍然间刀光一闪而逝，手中刀刃已向$n的$l横劈而去劲力刚猛，有力劈华山之势！。]],["id"]=[[34005]],["moveId"]=70040,["seriesId"]=34},["340050"]={["action"]=[[破空声起，一柄$w掷向$n，$n仓促阻挡，猛然间一道身影腾起，一记「$M」凭空接刃又出两刀，气势浩荡，惊动山河。]],["id"]=[[340050]],["moveId"]=70430,["seriesId"]=34},["340051"]={["action"]=[[破空声起，一柄$w掷向$n，$n仓促阻挡，猛然间一道身影腾起，一记「$M」凭空接刃又出两刀，气势浩荡，惊动山河。]],["id"]=[[340051]],["moveId"]=70440,["seriesId"]=34},["340052"]={["action"]=[[$N牢牢盯着定$n$l，手中$w有感而发，一招「$M」使来令人眼花缭乱，力可劈山。]],["id"]=[[340052]],["moveId"]=70450,["seriesId"]=34},["340053"]={["action"]=[[$N神色一肃，使出一招「$M」，手舞$w来回劈斩，身与刀似乎合二为一，一刀斩向$n$l，劲力无双，力可劈山！]],["id"]=[[340053]],["moveId"]=70460,["seriesId"]=34},["340054"]={["action"]=[[$N斜身飞起，身若惊鸿，带出一片片匹练也似的刀光卷向$n的$l，刀影飘忽，宛若山中云雾，正是一招「$M」。]],["id"]=[[340054]],["moveId"]=70470,["seriesId"]=34},["340055"]={["action"]=[[$N冷笑一声，双手握住长刀，凌空斩向$n$l，声势浩荡，力可劈山，正是一招「$M」。]],["id"]=[[340055]],["moveId"]=70480,["seriesId"]=34},["340056"]={["action"]=[[$N疾走向前，使一招「$M」，手中$w甩手一丢，掷向$n，$n只觉眼前一花，$N竟又接刀斩来，竟有惊动山河之威。]],["id"]=[[340056]],["moveId"]=70490,["seriesId"]=34},["340057"]={["action"]=[[只见$N刚一跃起，手中$w闪过道道白光，片刻间已对$n劈出三刀，劲力之强，竟好似泰山下压一般。正是一招「$M」。]],["id"]=[[340057]],["moveId"]=70500,["seriesId"]=34},["340058"]={["action"]=[[只见$N刚一跃起，手中$w闪过道道白光，片刻间已对$n劈出三刀，劲力之强，竟好似泰山下压一般。正是一招「$M」。]],["id"]=[[340058]],["moveId"]=70510,["seriesId"]=34},["34006"]={["action"]=[[$N轻蔑一笑，使出一招「$M」，手中$w缓缓挥出，斩向$n的$l，看似漫不经心，实则威力刚猛，有排山倒海之势。]],["id"]=[[34006]],["moveId"]=70040,["seriesId"]=34},["34007"]={["action"]=[[$N向后疾退，将手中$w高举过头顶，一招「$M」将$w横削而出，一股浩荡劲力涌出，逼向$n的$l，颇有横劈高山之威。]],["id"]=[[34007]],["moveId"]=70040,["seriesId"]=34},["34008"]={["action"]=[[$N使一式「$M」，神色微变，刀势陡然变得凌厉无比，手中$w如匹练一般洒向$n的$l，若山中迷雾，诡秘莫测！]],["id"]=[[34008]],["moveId"]=70050,["seriesId"]=34},["34009"]={["action"]=[[$N算准$n行径路线，一招「$M」半途截杀而出，手中$w在半空划出一道月牙，欲将$n一刀两断，招法雄劲，有劈山之威！]],["id"]=[[34009]],["moveId"]=70060,["seriesId"]=34},["35001"]={["action"]=[[$N进退之间突然神色一凛，使出一招「$M」，手中$w若猛虎下山般横劈而出，斩向$n的$l。]],["id"]=[[35001]],["moveId"]=70010,["seriesId"]=35},["350010"]={["action"]=[[$N进退之间突然神色一凛，使出一招「$M」，手中$w若猛虎下山般横劈而出，斩向$n的$l。]],["id"]=[[350010]],["moveId"]=70070,["seriesId"]=35},["350011"]={["action"]=[[$N跳上前来，使出一招「$M」，动作迅捷无比，有如饿虎扑食。只见$N将$w猛斩而出，挟裹一股劲风，刮向$n的$l。]],["id"]=[[350011]],["moveId"]=70070,["seriesId"]=35},["350012"]={["action"]=[[$N使出一招「$M」，一刀横斩，招法怪异，模仿老虎横尾猛扫之姿，向$n的$l猛攻猛攻而去。]],["id"]=[[350012]],["moveId"]=70070,["seriesId"]=35},["350013"]={["action"]=[[$N跃于空中，只见$N凌空一晃，使出一招「$M」，身形如饿虎扑食般向着$n冲去，手中$w直劈$n的$l。]],["id"]=[[350013]],["moveId"]=70080,["seriesId"]=35},["350014"]={["action"]=[[$N使出一招「$M」，凌空下斩，激起浩荡刀劲，涌向$n的$l，风声凛冽，宛若山中虎啸。]],["id"]=[[350014]],["moveId"]=70090,["seriesId"]=35},["350015"]={["action"]=[[$N跃至半空，使出一招「$M」，双手握住$w，一招下斩攻向$n的$l，招式看似平庸，却有猛虎下山之威！]],["id"]=[[350015]],["moveId"]=70100,["seriesId"]=35},["350016"]={["action"]=[[只见$N嘴角上扬，拇指在$w刃口一按，$w猛然激射而出。利刃划破长空，若猛虎前扑，直击$n$l。]],["id"]=[[350016]],["moveId"]=70110,["seriesId"]=35},["350017"]={["action"]=[[只见$N身形随风而动，蓦然间神色一肃，手中$w激起怪异之声，如若空山虎啸，直逼$n的$l。正是一招「$M」。]],["id"]=[[350017]],["moveId"]=70120,["seriesId"]=35},["350018"]={["action"]=[[$N进退之间突然神色一凛，使出一招「$M」，手中$w若猛虎下山般横劈而出，斩向$n的$l。]],["id"]=[[350018]],["moveId"]=70130,["seriesId"]=35},["350019"]={["action"]=[[$N跳上前来，使出一招「$M」，动作迅捷无比，有如饿虎扑食。只见$N将$w猛斩而出，挟裹一股劲风，刮向$n的$l。]],["id"]=[[350019]],["moveId"]=70130,["seriesId"]=35},["35002"]={["action"]=[[$N跳上前来，使出一招「$M」，动作迅捷无比，有如饿虎扑食。只见$N将$w猛斩而出，挟裹一股劲风，刮向$n的$l。]],["id"]=[[35002]],["moveId"]=70010,["seriesId"]=35},["350020"]={["action"]=[[$N使出一招「$M」，一刀横斩，招法怪异，模仿老虎横尾猛扫之姿，向$n的$l猛攻猛攻而去。]],["id"]=[[350020]],["moveId"]=70130,["seriesId"]=35},["350021"]={["action"]=[[$N以退为进，暗中掌握住节奏，使一招「$M」，须臾间手中$w若卧虎出山，轻灵一挥，刀未及体，刀风却触到了$n的$l。]],["id"]=[[350021]],["moveId"]=70140,["seriesId"]=35},["350022"]={["action"]=[[$N横刀立马，静候来击。须臾间$N一刀横斩，若虎跃山林，直直斩向$n的$l。]],["id"]=[[350022]],["moveId"]=70150,["seriesId"]=35},["350023"]={["action"]=[[$N横刀立马，静候来击。须臾间$N一刀横斩，若虎跃山林，直直斩向$n的$l。]],["id"]=[[350023]],["moveId"]=70160,["seriesId"]=35},["350024"]={["action"]=[[$N凝神聚意，眼前的景象似乎慢慢放缓，霎那间$N由静转动，迅若猛虎，手中$w连连劈出，连绵不绝攻向$n的$l。]],["id"]=[[350024]],["moveId"]=70170,["seriesId"]=35},["350025"]={["action"]=[[$N使出一招「$M」，一刀递出，劲力翻腾，如猛虎下山般冲向$n$l。]],["id"]=[[350025]],["moveId"]=70180,["seriesId"]=35},["350026"]={["action"]=[[$N使出一招「$M」，向后疾退，凌空出刀，如若猛虎出击，攻向$n$l。]],["id"]=[[350026]],["moveId"]=70190,["seriesId"]=35},["350027"]={["action"]=[[$N使出一招「$M」，身形前纵，矫健如虎，一刀直出，直斩向$n$l。]],["id"]=[[350027]],["moveId"]=70200,["seriesId"]=35},["350028"]={["action"]=[[$N突然一个箭步猛冲，若猛虎前扑，来到$n侧翼，手持$w抬手就砍，眨眼间两刀已然劈向$n的$l。]],["id"]=[[350028]],["moveId"]=70210,["seriesId"]=35},["350029"]={["action"]=[[$N使出一招「$M」，紧握手中$w上撩而出，有若虎跃高山，霎时三道刀光洒出，罩向n$l。]],["id"]=[[350029]],["moveId"]=70220,["seriesId"]=35},["35003"]={["action"]=[[$N使出一招「$M」，一刀横斩，招法怪异，模仿老虎横尾猛扫之姿，向$n的$l猛攻猛攻而去。]],["id"]=[[35003]],["moveId"]=70010,["seriesId"]=35},["350030"]={["action"]=[[只见$w利刃出鞘，$N身影动若猛虎，于平地、半空劈出两刀，刀气浩荡，涌向$n的$l。]],["id"]=[[350030]],["moveId"]=70230,["seriesId"]=35},["350031"]={["action"]=[[破空声起，却是一柄$w掷向$n，$n仓促阻挡，猛然间一道身影飞起，如虎跃山林，凭空一刀斩向$n$l，竟是$N使出一招「$M」。]],["id"]=[[350031]],["moveId"]=70240,["seriesId"]=35},["350032"]={["action"]=[[$N使出一招「$M」，前纵而出，来到$n左侧，一刀横拉，若猛虎扫尾，斩向$n$l。]],["id"]=[[350032]],["moveId"]=70250,["seriesId"]=35},["350033"]={["action"]=[[只见$N上一刻还在数丈之外，眨眼间攻入$n几寸之前，一招「$M」猛然攻向$n的$l，招法强悍，有伏熊擒虎之威。]],["id"]=[[350033]],["moveId"]=70260,["seriesId"]=35},["350034"]={["action"]=[[$N使出一招「$M」，身形猛地前纵，宛若饿虎扑食，挥洒手中$w，但见层层劲力涌出，罩向$n$l。]],["id"]=[[350034]],["moveId"]=70270,["seriesId"]=35},["350035"]={["action"]=[[只闻$N一声叹息，刀光骤起在半空闪烁两次，若虎爪连挥，直攻$n$l欲将$n劈成三截。]],["id"]=[[350035]],["moveId"]=70280,["seriesId"]=35},["350036"]={["action"]=[[只闻$N一声叹息，刀光骤起在半空闪烁两次，若虎爪连挥，直攻$n$l欲将$n劈成三截。]],["id"]=[[350036]],["moveId"]=70290,["seriesId"]=35},["350037"]={["action"]=[[$N目中狠厉一闪而过，使出一招「$M」，不闪不避持刀直劈$n面门，刀锋激起的劲声有若虎啸，威势骇人。]],["id"]=[[350037]],["moveId"]=70300,["seriesId"]=35},["350038"]={["action"]=[[$N目中狠厉一闪而过，使出一招「$M」，不闪不避持刀直劈$n面门，刀锋激起的劲声有若虎啸，威势骇人。]],["id"]=[[350038]],["moveId"]=70310,["seriesId"]=35},["350039"]={["action"]=[[$N腾身挪步跃于空中，使出一招「$M」，只见$N凌空一晃，身形如猛虎扑兔般向着$n俯冲而来，手中$w直劈$n的$l。]],["id"]=[[350039]],["moveId"]=70320,["seriesId"]=35},["35004"]={["action"]=[[$N以退为进，暗中掌握住节奏，使一招「$M」，须臾间手中$w若卧虎出山，轻灵一挥，刀未及体，刀风却触到了$n的$l。]],["id"]=[[35004]],["moveId"]=70030,["seriesId"]=35},["350040"]={["action"]=[[$N腾身挪步跃于空中，使出一招「$M」，只见$N凌空一晃，身形如猛虎扑兔般向着$n俯冲而来，手中$w直劈$n的$l。]],["id"]=[[350040]],["moveId"]=70330,["seriesId"]=35},["350041"]={["action"]=[[$N迎风而上，使出一招「$M」，手中的$w随风狂舞，一刀斩出，劲风激荡，若呼啸山林，径直裹向$n的$l。]],["id"]=[[350041]],["moveId"]=70340,["seriesId"]=35},["350042"]={["action"]=[[$N单手擎刀，使出一招「$M」，凌空下斩，一如猛虎下山！霎那间$w宛如劈山大斧，朝着$n$l狠劈而去。]],["id"]=[[350042]],["moveId"]=70350,["seriesId"]=35},["350043"]={["action"]=[[$N使出一招「$M」，三刀豁然而出，劲道之刚猛，宛若三只猛虎同出，咬向$n$l。]],["id"]=[[350043]],["moveId"]=70360,["seriesId"]=35},["350044"]={["action"]=[[霎时间$w刀鸣不止宛若虎啸，一发不可收，只见$N手握$w身形起落不定，使一招「$M」出刀攻向$n$l，欲将$n斩于刀下。]],["id"]=[[350044]],["moveId"]=70370,["seriesId"]=35},["350045"]={["action"]=[[只见$N快步向前，若猛虎狂奔，刀锋划破苍穹，斩向$n的$l。正是一招「$M」。]],["id"]=[[350045]],["moveId"]=70380,["seriesId"]=35},["350046"]={["action"]=[[$N腾身挪步跃于空中，使出一招「$M」，只见$N凌空一晃，身形如猛虎扑兔般向着$n俯冲而来，手中$w直劈$n的$l。]],["id"]=[[350046]],["moveId"]=70390,["seriesId"]=35},["350047"]={["action"]=[[$N盘身驻地，一招「$M」徒然使出，挥出一片刀影，劲力浩荡，似有数只猛虎向$n$l狂奔而去。]],["id"]=[[350047]],["moveId"]=70400,["seriesId"]=35},["350048"]={["action"]=[[$N提刀出击，使出一招「$M」，出刀迅捷无比，每刀之间已无间隙，向劲力之强，如若虎爪前挥，向$n$l猛攻而去。]],["id"]=[[350048]],["moveId"]=70410,["seriesId"]=35},["350049"]={["action"]=[[$N提刀出击，使出一招「$M」，出刀迅捷无比，每刀之间已无间隙，向劲力之强，如若虎爪前挥，向$n$l猛攻而去。]],["id"]=[[350049]],["moveId"]=70420,["seriesId"]=35},["35005"]={["action"]=[[$N进退之间突然神色一凛，使出一招「$M」，手中$w若猛虎下山般横劈而出，斩向$n的$l。]],["id"]=[[35005]],["moveId"]=70040,["seriesId"]=35},["350050"]={["action"]=[[$N使出一招「$M」，信手一掷，身形前纵，宛若饿虎扑食，手中$w划破长空斩向$n$l，招法绝妙，威力无双。]],["id"]=[[350050]],["moveId"]=70430,["seriesId"]=35},["350051"]={["action"]=[[$N使出一招「$M」，信手一掷，身形前纵，宛若饿虎扑食，手中$w划破长空斩向$n$l，招法绝妙，威力无双。]],["id"]=[[350051]],["moveId"]=70440,["seriesId"]=35},["350052"]={["action"]=[[$w身形前纵，若猛虎前扑，使出一招「$M」，手中$w连绵出招，对着$n的$l劈来劈去，动作连贯，行云流水。]],["id"]=[[350052]],["moveId"]=70450,["seriesId"]=35},["350053"]={["action"]=[[$N一刀一刀缓缓挥出，刀势慢如老牛，但挥刀收尾之际，$N登时动如而猛虎，向$n直奔而去。正是一招「$M」。]],["id"]=[[350053]],["moveId"]=70460,["seriesId"]=35},["350054"]={["action"]=[[$N展身虚步，提腰跃落，若猛虎下山，一招「$M」使来，刀锋上下开合，蓄力斩向$n$l。]],["id"]=[[350054]],["moveId"]=70470,["seriesId"]=35},["350055"]={["action"]=[[$N飞身上前，使一招「$M」，若虎跃山林，手臂上肌肉虬结，霎那间手持$w挥舞宛如挥戈劈斧，直直朝着$n扫来荡去。]],["id"]=[[350055]],["moveId"]=70480,["seriesId"]=35},["350056"]={["action"]=[[$N假意丢出$w蒙蔽$n，只见$N身如鬼魅，使出一招「$M」，反手捞回$w，横劈一刀，若虎爪前挥，刀法当真巧妙绝伦。]],["id"]=[[350056]],["moveId"]=70490,["seriesId"]=35},["350057"]={["action"]=[[只听$N大喝一声，使出一招「$M」，高高举起跃起，手中$w对着$n就是一顿猛劈，刀势刚猛宛如猛虎下山。]],["id"]=[[350057]],["moveId"]=70500,["seriesId"]=35},["350058"]={["action"]=[[只听$N大喝一声，使出一招「$M」，高高举起跃起，手中$w对着$n就是一顿猛劈，刀势刚猛宛如猛虎下山。]],["id"]=[[350058]],["moveId"]=70510,["seriesId"]=35},["35006"]={["action"]=[[$N跳上前来，使出一招「$M」，动作迅捷无比，有如饿虎扑食。只见$N将$w猛斩而出，挟裹一股劲风，刮向$n的$l。]],["id"]=[[35006]],["moveId"]=70040,["seriesId"]=35},["35007"]={["action"]=[[$N使出一招「$M」，一刀横斩，招法怪异，模仿老虎横尾猛扫之姿，向$n的$l猛攻猛攻而去。]],["id"]=[[35007]],["moveId"]=70040,["seriesId"]=35},["35008"]={["action"]=[[$N错步上前，使出「$M」，手持利刃，刀意若有若无，若虎伏山林，洋洋洒洒向$n的$l挥去。]],["id"]=[[35008]],["moveId"]=70050,["seriesId"]=35},["35009"]={["action"]=[[$N以退为进，暗中掌握住节奏，使一招「$M」，须臾间手中$w若卧虎出山，轻灵一挥，刀未及体，刀风却