iesId"]=61},["61002"]={["action"]=[[$n一言不发，使出一招「$M」，原地凝立，宛若青山，待$P攻来，运转劲力想迎，竟极为轻松地接下了这一招。]],["id"]=[[61002]],["moveId"]=150020,["seriesId"]=61},["61003"]={["action"]=[[$n大喝一声，使出一招「$M」，运转刚猛劲力迎上$P这一击，只听得一声巨响，宛若山石崩裂。$P的攻势已然被遏制住了！]],["id"]=[[61003]],["moveId"]=150030,["seriesId"]=61},["61004"]={["action"]=[[$n身形前探，使出一招「$M」，宛若高山般直迎上了$P的攻势，竟是硬生生拦住了这一击！]],["id"]=[[61004]],["moveId"]=150040,["seriesId"]=61},["62001"]={["action"]=[[$n不闪不避，施展一招「$M」，防守若铁板一块。$P攻来若敲打在铁板之上，毫无作用。]],["id"]=[[62001]],["moveId"]=150010,["seriesId"]=62},["62002"]={["action"]=[[$n暴喝一声，身形窜出，一招「$M」迎敌，守势浑若钢铁，抵住$P的这一轮猛攻。]],["id"]=[[62002]],["moveId"]=150020,["seriesId"]=62},["62003"]={["action"]=[[$n使出一招「$M」，无丝毫躲闪之意，聚气格挡，如若坚铁附体，竟是以强克强，挡住了$P这一招。]],["id"]=[[62003]],["moveId"]=150030,["seriesId"]=62},["62004"]={["action"]=[[$n奋力前冲，使出一招「$M」，守势若百炼钢铁，密不透风，$P虽是一番猛攻，却是毫无成效。]],["id"]=[[62004]],["moveId"]=150040,["seriesId"]=62},["63001"]={["action"]=[[$n身形窜出，一招「$M」迎敌，守势若千钧岩石，刚硬无比，抵住$P的这一轮猛攻。]],["id"]=[[63001]],["moveId"]=150010,["seriesId"]=63},["63002"]={["action"]=[[$n二话不说，迎上$P的攻击，近身之后，使出一招「$M」，守势坚若磐石，将$P的攻势尽数化解。]],["id"]=[[63002]],["moveId"]=150020,["seriesId"]=63},["63003"]={["action"]=[[$n立稳身姿，瞧准$P来招疏漏之处，一招「$M」使出，竟好似天落巨石，将$P的攻击尽数压了回去。]],["id"]=[[63003]],["moveId"]=150030,["seriesId"]=63},["63004"]={["action"]=[[$n使出一招「$M」，霎时气劲翻涌，刚猛无比，周身宛若巨石，出手格挡，竟是硬生生挡住了$P的刚猛一击。]],["id"]=[[63004]],["moveId"]=150040,["seriesId"]=63},["64001"]={["action"]=[[$n一招「$M」抱架而立，气势高涨，身若苍松誓要硬捍天雷，奋力挡下$P攻势。]],["id"]=[[64001]],["moveId"]=150010,["seriesId"]=64},["64002"]={["action"]=[[只听$n不屑一笑，闭目施出一招「$M」,顿时身姿宛若雷打不动，将$P攻击尽数格挡。]],["id"]=[[64002]],["moveId"]=150020,["seriesId"]=64},["64003"]={["action"]=[[$n眼中精芒闪烁，须臾间一招「$M」发如雷霆，直让$P攻势烟消云散。]],["id"]=[[64003]],["moveId"]=150030,["seriesId"]=64},["64004"]={["action"]=[[霎时间只听雷声大作，金鼓齐鸣，竟是$n使出一招「$M」与$P攻势相敌，将凌厉攻势阻挡在外。]],["id"]=[[64004]],["moveId"]=150040,["seriesId"]=64},["65001"]={["action"]=[[$n一招「$M」，身形抱架可谓滴水不漏，叫$P万般攻势石沉大海。]],["id"]=[[65001]],["moveId"]=150010,["seriesId"]=65},["65002"]={["action"]=[[只见$n一招「$M」，兵来将挡，水来土掩，将$P攻势尽数抵挡。]],["id"]=[[65002]],["moveId"]=150020,["seriesId"]=65},["65003"]={["action"]=[[$n一招「$M」使出，激出道道气劲，气流仿佛在身前积水成渊，让$P攻势好似打进深渊之中。]],["id"]=[[65003]],["moveId"]=150030,["seriesId"]=65},["65004"]={["action"]=[[$P攻势不断侵袭，却见$n一招「$M」好似一瓢冷水兜头浇向$P，把$P如火的攻势平息。]],["id"]=[[65004]],["moveId"]=150040,["seriesId"]=65},["66001"]={["action"]=[[$N使一招「$M」，身形如风而逝，向右躲过了$n的攻击。]],["id"]=[[66001]],["moveId"]=130010,["seriesId"]=66},["660010"]={["action"]=[[$N施展一招「$M」，身形矫健如风，膝盖下沉，前滑数尺，巧妙避过了$n的全部攻击。]],["id"]=[[660010]],["moveId"]=130100,["seriesId"]=66},["660011"]={["action"]=[[$N用出一招「$M」，身子腾空而起，宛若狂风乍临，转瞬便避过了$n的全部攻击。]],["id"]=[[660011]],["moveId"]=130110,["seriesId"]=66},["660012"]={["action"]=[[$N身子左右浮动，施展一招「$M」，若疾风般飞速闪转，幻出数道身影，不费吹灰之力便避过了$n的全部攻击。]],["id"]=[[660012]],["moveId"]=130120,["seriesId"]=66},["660013"]={["action"]=[[$N施展一招「$M」，身形倏的从$n的眼前飘过，再向后空翻，若狂风刮过，动作潇洒之极，轻松避过了$n的全部攻击。]],["id"]=[[660013]],["moveId"]=130130,["seriesId"]=66},["660014"]={["action"]=[[$N施展一招「$M」，向前飞闪至$n一旁，身形疾卷，有若风中羽毛，飘动之中便避过了$n的全部攻击。]],["id"]=[[660014]],["moveId"]=130140,["seriesId"]=66},["660015"]={["action"]=[[$N身形侧滑而出，有若风中浮萍，将$n的一招轻松避过。]],["id"]=[[660015]],["moveId"]=130150,["seriesId"]=66},["660016"]={["action"]=[[$N疾纵而出，带起一阵狂风，$n一招落空，方才发觉$N已跃到了自己身后。]],["id"]=[[660016]],["moveId"]=130160,["seriesId"]=66},["660017"]={["action"]=[[$N高高跃起，身形快若旋风，左右腾挪之间，竟避过了$N的尽数招式。]],["id"]=[[660017]],["moveId"]=130170,["seriesId"]=66},["66002"]={["action"]=[[$N使出一招「$M」，身形如若狂风横扫般向后疾飞，避过了$n的攻击。]],["id"]=[[66002]],["moveId"]=130020,["seriesId"]=66},["66003"]={["action"]=[[$N使出一招「$M」，身形上窜，如若狂风疾卷，竟恰好避过了$n的攻击。]],["id"]=[[66003]],["moveId"]=130030,["seriesId"]=66},["66004"]={["action"]=[[$N使出一招「$M」，身形闪动，在空中如若龙卷刮过，轻易避过了$n的攻击。]],["id"]=[[66004]],["moveId"]=130040,["seriesId"]=66},["66005"]={["action"]=[[$N施展一招「$M」，身形向后飞撤，有若阴风刮过，竟让$n的攻击尽数落空！]],["id"]=[[66005]],["moveId"]=130050,["seriesId"]=66},["66006"]={["action"]=[[$N施展一招「$M」，身子左右扭动，动作迅捷如风，竟避过了$n的全部攻击。]],["id"]=[[66006]],["moveId"]=130060,["seriesId"]=66},["66007"]={["action"]=[[$N施展一招「$M」，身子竟似化作了一股清风，缥缈至极，避过了$n的全部攻击。]],["id"]=[[66007]],["moveId"]=130070,["seriesId"]=66},["66008"]={["action"]=[[$N轻笑一声，使出一招「$M」，身子若疾风般高高拔起，避过了$n的全部攻击。]],["id"]=[[66008]],["moveId"]=130080,["seriesId"]=66},["66009"]={["action"]=[[$N神色自若，施展一招「$M」，身子在空中连续翻滚，若旋风凌空，轻松避过了$n的全部攻击。]],["id"]=[[66009]],["moveId"]=130090,["seriesId"]=66},["67001"]={["action"]=[[$N使出「$M」，大踏步上前，全身宛如电光环绕，身形飘忽，虚影远逝，去势难料。]],["id"]=[[67001]],["moveId"]=130010,["seriesId"]=67},["670010"]={["action"]=[[$N一式「$M」，只见$N身子后仰，双掌往地下一撑，身子借势电射而出，好似平地惊雷。]],["id"]=[[670010]],["moveId"]=130100,["seriesId"]=67},["670011"]={["action"]=[[$N一式「$M」，纵高伏低，东奔西闪，身形飘忽如电，$n手无足措，只得回招自守。]],["id"]=[[670011]],["moveId"]=130110,["seriesId"]=67},["670012"]={["action"]=[[$N一式「$M」，突然反身一跳，电掣雷行，竟然是逼身向前，欲图围魏救赵。]],["id"]=[[670012]],["moveId"]=130120,["seriesId"]=67},["670013"]={["action"]=[[$N一式「$M」，不招不架，只微微一侧身，犹如暴雨急电，让$n的进攻便即落空。]],["id"]=[[670013]],["moveId"]=130130,["seriesId"]=67},["670014"]={["action"]=[[$N一式「$M」，蓦然间身形拔起，直冲云霄，快若飞点，几个盘旋，飘飘荡荡落在数丈之外。]],["id"]=[[670014]],["moveId"]=130140,["seriesId"]=67},["670015"]={["action"]=[[$N一式「$M」，身形急速旋转，转若电蛇，几下就划到数丈之外。]],["id"]=[[670015]],["moveId"]=130150,["seriesId"]=67},["670016"]={["action"]=[[只见$N一招「$M」，身体向上笔直地纵起丈余，化作疾电上九天，躲过了$n的攻势。]],["id"]=[[670016]],["moveId"]=130160,["seriesId"]=67},["670017"]={["action"]=[[$N一个「$M」，身似鬼出电入，向后纵出数丈之远，避开了$n的凌厉攻势。]],["id"]=[[670017]],["moveId"]=130170,["seriesId"]=67},["67002"]={["action"]=[[$N使出「$M」，身形急速闪动，向前飞窜而出，化作一道电矢，眨眼间便了无踪迹。]],["id"]=[[67002]],["moveId"]=130020,["seriesId"]=67},["67003"]={["action"]=[[$N一招「$M」，身形宛如电蛇翻转腾挪，只见$N身影闪烁，以急速身法避开凌厉攻击。]],["id"]=[[67003]],["moveId"]=130030,["seriesId"]=67},["67004"]={["action"]=[[$N一招「$M」，身形飞逝如电，竟躲过了$n的猛烈攻势。]],["id"]=[[67004]],["moveId"]=130040,["seriesId"]=67},["67005"]={["action"]=[[$N一招「$M」，双腿急奔，身形来去如电，一时之间直教$n看不出自身所在。]],["id"]=[[67005]],["moveId"]=130050,["seriesId"]=67},["67006"]={["action"]=[[$N一招「$M」，跃至半空，身形急转，好似逐电一般，转眼欺近$n身旁。]],["id"]=[[67006]],["moveId"]=130060,["seriesId"]=6