eId"]=140040,["seriesId"]=83},["83005"]={["action"]=[[$n施展一招「$M」，勉力接招，竟挡住了这一轮的攻势。]],["id"]=[[83005]],["moveId"]=140050,["seriesId"]=83},["84001"]={["action"]=[[只见$N挥出双掌，左掌横贯左右，右掌竖劈苍穹，带动衣襟猎猎作响，正是一招「$M」。]],["id"]=[[84001]],["moveId"]=1000201,["seriesId"]=[[84]]},["840010"]={["action"]=[[只见一招「$M」，$N眼中嗜血一闪而过，平平一掌，斩向$n脖颈。单掌掠出一道圆弧，看似轻描淡写，实则避无可避，防不胜防。]],["id"]=[[840010]],["moveId"]=1000210,["seriesId"]=[[84]]},["840011"]={["action"]=[[$N使出一式「$M」，岿然不动，卖出破绽只等$n来攻。突然间身形一错，让过来击，反手一掌拍向$n的$l。]],["id"]=[[840011]],["moveId"]=1000211,["seriesId"]=[[84]]},["840012"]={["action"]=[[只见$N捧起双掌，摇头晃脑宛若读书，突然并起双掌使出一式「$M」，掌力飘飘洒洒虚虚实实，攻向$n的$l。]],["id"]=[[840012]],["moveId"]=1000212,["seriesId"]=[[84]]},["840013"]={["action"]=[[$N双手平举，扭转身形，将身子转得像一陀螺，两掌频频拍出，掌力连绵不断。正是一招「$M」。]],["id"]=[[840013]],["moveId"]=1000213,["seriesId"]=[[84]]},["840014"]={["action"]=[[$N吐出一口浊气使出一式「$M」，一掌接着一掌打向$n的$l，指力滔滔不绝，丝毫不给$n片刻喘息的机会。]],["id"]=[[840014]],["moveId"]=1000214,["seriesId"]=[[84]]},["840015"]={["action"]=[[只见$N立地抱拳，头发衣袍无风而动，气势节节攀升。须臾间$N神色一肃，双掌击向$n，有去无回，义无反顾。正是一招「$M」。]],["id"]=[[840015]],["moveId"]=1000215,["seriesId"]=[[84]]},["840016"]={["action"]=[[$N进退有度，与$n始终若即若离，看准时机时不时拍出一掌，拍向$n周身穴道。正是一招「$M」。]],["id"]=[[840016]],["moveId"]=1000216,["seriesId"]=[[84]]},["840017"]={["action"]=[[$N使出一招「$M」踏前一步，仰天长啸，左手一挥，肃清宇内，右手一挥，挥斥方遒。]],["id"]=[[840017]],["moveId"]=1000217,["seriesId"]=[[84]]},["84002"]={["action"]=[[$N双眼含恨，伏下身躯，脚步看似杂乱无章，实则坚定向前，须臾间身形一错，挥掌直取$n空门。正是一招「$M」。]],["id"]=[[84002]],["moveId"]=1000202,["seriesId"]=[[84]]},["84003"]={["action"]=[[$N弯腰隆背，将千钧之力藏于双掌之上，看准时机猛然拜倒在$n身前，一双肉掌以雷霆之势拍出，欲将$n双腿拍断。正是一招「$M」。]],["id"]=[[84003]],["moveId"]=1000203,["seriesId"]=[[84]]},["84004"]={["action"]=[[$N猱身而上使出一招「$M」，左掌虚虚实实，直探$n心口，右掌揽出一个圆弧，从一个诡异刁钻的角度拍向$n后脑。]],["id"]=[[84004]],["moveId"]=1000204,["seriesId"]=[[84]]},["84005"]={["action"]=[[只听$N一声大喝使出一招「$M」，宛若平地起惊雷，震得$n身形不稳。双掌挥出，霎时间，漫天掌影向$n席卷而去。]],["id"]=[[84005]],["moveId"]=1000205,["seriesId"]=[[84]]},["84006"]={["action"]=[[只见$N左掌立于胸前，右掌藏于身后，高高跃起，左掌推向$n的同时，右掌携泰山压顶之势狠贯而下。正是一招「$M」。]],["id"]=[[84006]],["moveId"]=1000206,["seriesId"]=[[84]]},["84007"]={["action"]=[[只见一招「$M」，$N先退三尺，凝神聚气，双掌如飞鸟振翅，从两侧推出，霎时间掌风密布，道道掌风刮向$n。]],["id"]=[[84007]],["moveId"]=1000207,["seriesId"]=[[84]]},["84008"]={["action"]=[[$N低喝一声，不顾对方攻势，一往无前，闯入$n空门，单掌掠向$n咽喉。正是一招「$M」。]],["id"]=[[84008]],["moveId"]=1000208,["seriesId"]=[[84]]},["84009"]={["action"]=[[只见一招「$M」，$N拱手抱拳，忽然间双掌化作刀斧，大开大合直斩$n项上人头。]],["id"]=[[84009]],["moveId"]=1000209,["seriesId"]=[[84]]},["9"]={["action"]=[[$N武功不够纯熟，身形一倾，打出一招威力颇弱的「$M」。]],["id"]=[[9]],["moveId"]=1010900,["seriesId"]=[[0]]},["9001"]={["action"]=[[$N全身聚气于单臂，使出一招「$M」，似天雷降世，势不可挡地朝$n的$l重击。]],["id"]=[[9001]],["moveId"]=10010,["seriesId"]=9},["90010"]={["action"]=[[$N单拳晃动，挺身一招「$M」，似雷奔云谲般，连续两次打向$n$l。]],["id"]=[[90010]],["moveId"]=10110,["seriesId"]=9},["90011"]={["action"]=[[$N右拳直出，一式「$M」运满劲力，雷厉风行地朝$n的$l双击。]],["id"]=[[90011]],["moveId"]=10120,["seriesId"]=9},["90012"]={["action"]=[[$N高举右拳，顺势使出一招「$M」，只见那右拳如晴天霹雳一般，轰隆两声巨响，砸向$n的$l。]],["id"]=[[90012]],["moveId"]=10130,["seriesId"]=9},["90013"]={["action"]=[[$N脚步瞬移上前，使出一招「$M」，单拳以势不可挡之威，若两道惊雷降临，接连打向$n的$l。]],["id"]=[[90013]],["moveId"]=10140,["seriesId"]=9},["90014"]={["action"]=[[$N使出一招「$M」，疾步冲上前，单拳迅猛出击，下劈电闪雷鸣，宛若两道雷光砸向$n的$l。]],["id"]=[[90014]],["moveId"]=10150,["seriesId"]=9},["90015"]={["action"]=[[$N流星踏步，看准时机，使出一招「$M」，单拳直攻向$n的$l，随即手腕一翻，朝上连劈，势若雷霆。]],["id"]=[[90015]],["moveId"]=10160,["seriesId"]=9},["90016"]={["action"]=[[$N内劲运转，一拳斜出，破空声如雷鸣，下劈暗袭似迅雷之速，这一招「$M」直击$n的$l。]],["id"]=[[90016]],["moveId"]=10160,["seriesId"]=9},["90017"]={["action"]=[[$N闷喝一声，双拳向上分开，一记「$M」，左拳划弧线引雷，右拳借雷威上劈，接连对准$n的$l击去。]],["id"]=[[90017]],["moveId"]=10160,["seriesId"]=9},["90018"]={["action"]=[[$N流星踏步，看准时机，使出一招「$M」，单拳直攻向$n的$l，随即手腕一翻，朝上连劈，势若雷霆。]],["id"]=[[90018]],["moveId"]=10170,["seriesId"]=9},["90019"]={["action"]=[[$N内劲运转，一拳斜出，破空声如雷鸣，下劈暗袭似迅雷之速，这一招「$M」直击$n的$l。]],["id"]=[[90019]],["moveId"]=10170,["seriesId"]=9},["9002"]={["action"]=[[$N单臂青筋暴起，一招「$M」好似运有雷霆之威，上劈快如闪电，单拳运有熊熊雷火一般砸向$n的$l。]],["id"]=[[9002]],["moveId"]=10030,["seriesId"]=9},["9